const statusBadge = (s: string): string => {
  switch (s) {
    case 'In Consult': return 'bg-emerald-100 text-emerald-700 border border-emerald-200';
    case 'Admitted':   return 'bg-blue-100 text-blue-700 border border-blue-200';
    case 'Waiting':    return 'bg-amber-100 text-amber-700 border border-amber-200';
    case 'Done':       return 'bg-slate-100 text-slate-600 border border-slate-200';
    default:           return 'bg-slate-100 text-slate-600 border border-slate-200';
  }
};

