export default function PatientsPage(): React.ReactElement {
  const [patientsList, setPatientsList] = useState<PatientSummary[]>(patients);
  const [search, setSearch] = useState<string>('');
  const [selectedId, setSelectedId] = useState<string>('1');
  const [activeTab, setActiveTab] = useState<TabType>('Overview');
  const [aiDraftVisible, setAiDraftVisible] = useState<boolean>(false);
  const [soap, setSoap] = useState<{ s: string; o: string; a: string; p: string }>({ s: '', o: '', a: '', p: '' });
  const [soapNotesState, setSoapNotesState] = useState<Record<string, SOAPNote[]>>(soapNotesByPatient);
    const [panelOpen, setPanelOpen] = useState(false);
    const [registrationOpen, setRegistrationOpen] = useState(false);
    const [aiTriageContext, setAiTriageContext] = useState<{ symptoms: string; context: string } | null>(null);
  const [fhirSummary, setFhirSummary] = useState<FhirSummaryPayload | null>(null);
  const [communityFollowUpRequired, setCommunityFollowUpRequired] = useState(false);
  const [communityFollowUpReason, setCommunityFollowUpReason] = useState('');

  useEffect(() => {
    const loadPatients = async () => {
      try {
        const response = await fetch('/api/data?entity=patients');
        if (!response.ok) return;
        const rows = await response.json() as Array<{
          id: string;
          pid?: string;
          name?: string;
          age?: number;
          gender?: 'M' | 'F';
          blood_group?: string;
          allergies?: string[];
          complaint?: string;
          status?: string;
        }>;
        if (!Array.isArray(rows) || rows.length === 0) return;
        const normalized: PatientSummary[] = rows.map((row, index) => ({
          id: row.id,
          pid: row.pid ?? `PID-${10000 + index}`,
          name: row.name ?? 'Unknown Patient',
          age: row.age ?? 0,
          sex: row.gender ?? 'M',
          bloodGroup: row.blood_group ?? 'Unknown',
          allergies: Array.isArray(row.allergies) ? row.allergies : [],
          complaint: row.complaint ?? 'General consultation',
          status: row.status ?? 'Waiting',
        }));
        setPatientsList(normalized);
        setSelectedId((prev) => (normalized.some((p) => p.id === prev) ? prev : normalized[0].id));
      } catch (error) {
        logger.warn('Falling back to local patient list', { error });
      }
    };
    void loadPatients();
  }, []);

  useEffect(() => {
    const loadFhirSummary = async () => {
      if (!selectedId) return;
      try {
        const response = await fetch(`/api/medical/patients/${selectedId}/fhir-summary`);
        if (!response.ok) {
          setFhirSummary(null);
          return;
        }
        const payload = await response.json() as FhirSummaryPayload;
        setFhirSummary(payload);
      } catch {
        setFhirSummary(null);
      }
    };
    void loadFhirSummary();
  }, [selectedId]);

    const filtered = patientsList.filter((p) =>
    p.name.toLowerCase().includes(search.toLowerCase()) ||
    p.pid.toLowerCase().includes(search.toLowerCase())
  );

  const selected = patientsList.find((p) => p.id === selectedId) ?? patientsList[0];
  const meds = medicationsByPatient[selected.id] ?? [];
  const problems = problemsByPatient[selected.id] ?? [];
    const notes = soapNotesState[selected.id] ?? [];
    const orders = ordersByPatient[selected.id] ?? [];

  const fhirMedicationNames = useMemo(
    () =>
      (fhirSummary?.medicationRequests ?? [])
        .map((med) => med.medicationCodeableConcept?.text?.trim())
        .filter((value): value is string => Boolean(value)),
    [fhirSummary],
  );

  const overviewMedications = useMemo(
    () =>
      fhirMedicationNames.length > 0
        ? fhirMedicationNames.map((name) => ({
            drug: name,
            dose: 'FHIR',
            freq: 'As documented',
            duration: 'Active',
          }))
        : meds,
    [fhirMedicationNames, meds],
  );

  const overviewVitals = useMemo<VitalTile[]>(() => {
    const fallback: VitalTile[] = [
      { label: 'BP', value: '158/96', unit: 'mmHg', color: 'text-rose-700' },
      { label: 'Pulse', value: '98', unit: 'bpm', color: 'text-amber-700' },
      { label: 'Temp', value: '37.4', unit: '°C', color: 'text-slate-900' },
      { label: 'SpO2', value: '94', unit: '%', color: 'text-amber-700' },
      { label: 'RR', value: '20', unit: '/min', color: 'text-slate-900' },
    ];

    const observations = fhirSummary?.observations ?? [];
    if (observations.length === 0) return fallback;

    const findByCode = (codeText: string): number | undefined =>
      observations.find((obs) => obs.code?.text === codeText)?.valueQuantity?.value;

    const systolic = findByCode('Systolic Blood Pressure');
    const diastolic = findByCode('Diastolic Blood Pressure');
    const pulse = findByCode('Heart Rate');
    const temp = findByCode('Body Temperature');
    const spo2 = findByCode('Oxygen Saturation');
    const rr = findByCode('Respiratory Rate');

    return [
      { label: 'BP', value: systolic && diastolic ? `${systolic}/${diastolic}` : fallback[0].value, unit: 'mmHg', color: 'text-rose-700' },
      { label: 'Pulse', value: pulse ? String(pulse) : fallback[1].value, unit: 'bpm', color: 'text-amber-700' },
      { label: 'Temp', value: temp ? String(temp) : fallback[2].value, unit: '°C', color: 'text-slate-900' },
      { label: 'SpO2', value: spo2 ? String(spo2) : fallback[3].value, unit: '%', color: 'text-amber-700' },
      { label: 'RR', value: rr ? String(rr) : fallback[4].value, unit: '/min', color: 'text-slate-900' },
    ];
  }, [fhirSummary]);

    const detailedPatient: PatientDetail = {
        ...MOCK_PATIENT_DETAIL,
        id: selected.id,
        name: selected.name,
        patient_id: selected.pid,
        age: selected.age,
        gender: selected.sex === 'M' ? 'Male' : 'Female',
        blood_type: selected.bloodGroup,
        allergies: selected.allergies.map(a => ({ substance: a, severity: 'moderate' })),
        conditions: problems.map(p => p.name),
        vitals: {
            bp: overviewVitals[0]?.value ?? '158/96',
            pulse: Number(overviewVitals[1]?.value ?? 98),
            spo2: Number(overviewVitals[3]?.value ?? 94),
            temp: `${overviewVitals[2]?.value ?? '37.4'}${overviewVitals[2]?.unit ?? '°C'}`,
            rr: Number(overviewVitals[4]?.value ?? 20),
            weight: '72 kg'
        },
        medications: overviewMedications.map(m => ({
            name: m.drug,
            dosage: m.dose,
            frequency: m.freq,
            active: true
        })),
        recent_records: notes.map(n => ({
            id: Math.random().toString(),
            date: n.date,
            type: 'Consultation',
            doctor: n.author,
            summary: n.assessment
        }))
    };

    const handleAnalysisSync = (analysis: any) => {
        if (analysis.soapDraft) {
            setSoap(prev => ({
                ...prev,
                s: analysis.soapDraft.subjective || prev.s,
                o: analysis.soapDraft.objective || prev.o,
                a: analysis.soapDraft.assessment || prev.a,
                p: analysis.soapDraft.plan || prev.p,
            }));
            toast.success('AI Scribe synchronized clinical draft', {
                description: 'Real-time SOAP insights updated.',
                icon: '✨'
            });
        } else {
            setSoap(prev => ({
                ...prev,
                s: prev.s ? `${prev.s}\n\nAI Summary: ${analysis.summary}` : `AI Summary: ${analysis.summary}`,
                a: prev.a ? `${prev.a}\n\nDifferential: ${analysis.differentialDiagnosis.map((d: any) => typeof d === 'string' ? d : d.diagnosis).join(', ')}` : `Differential: ${analysis.differentialDiagnosis.map((d: any) => typeof d === 'string' ? d : d.diagnosis).join(', ')}`,
                p: prev.p ? `${prev.p}\n\nAI Actions: ${analysis.recommendedActions.join('\n')}` : `AI Actions: ${analysis.recommendedActions.join('\n')}`
            }));
            toast.success('AI insights imported to SOAP notes');
        }
    };

    const handleTriageDeepDive = (symptoms: string) => {
        setAiTriageContext({
            symptoms,
            context: `Triage Report Deep Dive: ${selected.name} (${selected.pid})`
        });
        setPanelOpen(false);
        setActiveTab('Clinical AI');
    };

  const submitCommunityFollowUp = async (params: {
    patientRef: string;
    patientName: string;
    carePlan: string;
    followUpReason?: string;
  }) => {
    const upsertResponse = await fetch('/api/apps/chp/care-plans', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        patientRef: params.patientRef,
        patientName: params.patientName,
        carePlan: params.carePlan,
        communityFollowUpRequired: true,
        followUpReason: params.followUpReason,
        source: 'medical-portal.soap',
      }),
    });

    if (!upsertResponse.ok) {
      throw new Error(`CHP care plan upsert failed (${upsertResponse.status})`);
    }

    const confirmationResponse = await fetch(
      `/api/apps/chp/care-plans?patientRef=${encodeURIComponent(params.patientRef)}`,
    );
    if (!confirmationResponse.ok) {
      throw new Error(`CHP care plan confirmation failed (${confirmationResponse.status})`);
    }

    const confirmation = await confirmationResponse.json() as {
      found?: boolean;
      carePlanId?: string;
    };

    if (!confirmation.found || !confirmation.carePlanId) {
      throw new Error('CHP care plan confirmation returned no active record.');
    }

    toast.success('Community follow-up sent to CHP app', {
      description: `Care plan ID: ${confirmation.carePlanId}`,
    });
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <h1 className="text-2xl font-bold text-slate-900">Patient Workspace</h1>
        <button 
          onClick={() => setRegistrationOpen(true)}
          className="flex items-center gap-2 px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-sm font-medium transition-colors w-fit shadow-lg shadow-emerald-500/10"
        >
          <Plus className="w-4 h-4" /> New Patient
        </button>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
        <input
          type="text"
          placeholder="Search patients by name, PID, phone..."
          aria-label="Search patients by name, PID, or phone"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full pl-10 pr-4 py-2.5 rounded-lg bg-white border border-slate-300 text-slate-900 placeholder-slate-400 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Patient List */}
        <div className="lg:col-span-1 space-y-2 max-h-[600px] overflow-y-auto pr-1">
          {filtered.map((p) => (
            <button
              key={p.id}
              onClick={() => { setSelectedId(p.id); setActiveTab('Overview'); setAiDraftVisible(false); }}
              className={cn(
                'w-full text-left rounded-xl border p-4 transition-all',
                selectedId === p.id
                  ? 'bg-emerald-50 border-emerald-200 shadow-sm'
                  : 'bg-white border-slate-200 hover:border-slate-300 hover:shadow-sm'
              )}
            >
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="text-sm font-semibold text-slate-900">{p.name}</p>
                  <p className="text-xs text-slate-500">{p.pid} · {p.age}y {p.sex}</p>
                  <p className="text-xs text-slate-500 mt-1 truncate max-w-[180px]">{p.complaint}</p>
                </div>
                <div className="flex flex-col items-end gap-1">
                  <span className={cn('text-xs px-2 py-0.5 rounded-full', statusBadge(p.status))}>{p.status}</span>
                  <ChevronRight className="w-3.5 h-3.5 text-slate-400" />
                </div>
              </div>
            </button>
          ))}
        </div>

        {/* Patient Detail */}
        <div className="lg:col-span-2 rounded-xl bg-white border border-slate-200 overflow-hidden shadow-sm">
          {/* Patient Header */}
          <div className="px-5 py-4 border-b border-slate-200">
            <div className="flex flex-wrap items-start gap-3">
              <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-700 font-bold text-sm shrink-0">
                {selected.name.split(' ').map((n) => n[0]).join('').slice(0, 2)}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <h2 className="text-base font-bold text-slate-900">{selected.name}</h2>
                  <span className={cn('text-xs px-2 py-0.5 rounded-full', statusBadge(selected.status))}>{selected.status}</span>
                </div>
                <p className="text-xs text-slate-500">{selected.pid} · {selected.age}y {selected.sex} · {selected.bloodGroup}</p>
              </div>
              <div className="flex flex-wrap gap-1.5 items-center">
                {selected.allergies.length > 0
                  ? selected.allergies.map((a) => (
                      <span key={a} className="text-xs px-2 py-0.5 rounded bg-rose-100 text-rose-700 border border-rose-200">
                        ⚠ {a}
                      </span>
                    ))
                  : <span className="text-xs text-emerald-700 font-medium">NKDA</span>
                }
                <button 
                  onClick={() => setPanelOpen(true)}
                  className="ml-2 text-[10px] font-bold uppercase tracking-widest text-emerald-600 hover:text-emerald-700 flex items-center gap-1 border border-emerald-200 px-2 py-1 rounded-lg bg-emerald-50 transition-all shadow-sm"
                >
                  <Activity className="w-3 h-3" /> Deep Dive
                </button>
              </div>
            </div>
          </div>

          {/* Tabs */}
          <div className="flex border-b border-slate-200 overflow-x-auto">
            {TABS.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                aria-label={`${tab} tab`}
                aria-pressed={activeTab === tab}
                className={cn(
                  'px-5 py-3 text-sm font-medium whitespace-nowrap transition-colors',
                  activeTab === tab
                    ? 'text-emerald-700 border-b-2 border-emerald-600'
                    : 'text-slate-500 hover:text-slate-700'
                )}
              >
                {tab}
              </button>
            ))}
          </div>

          {/* Tab Content */}
          <div className="p-5">
            {activeTab === 'Overview' && (
              <div className="space-y-5">
                {/* Vitals */}
                <div>
                  <h3 className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-3 flex items-center gap-2">
                    <Activity className="w-3.5 h-3.5" /> Vitals
                  </h3>
                  <div className="grid grid-cols-5 gap-2">
                    {overviewVitals.map((v) => (
                      <div key={v.label} className="rounded-lg bg-white border border-slate-200 p-3 text-center shadow-sm">
                        <p className="text-xs text-slate-500">{v.label}</p>
                        <p className={cn('text-lg font-bold mt-1', v.color)}>{v.value}</p>
                        <p className="text-xs text-slate-500">{v.unit}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Current Medications */}
                <div>
                  <h3 className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-3 flex items-center gap-2">
                    <Pill className="w-3.5 h-3.5" /> Current Medications
                  </h3>
                  {overviewMedications.length === 0
                    ? <p className="text-sm text-slate-500">No active medications</p>
                    : (
                      <div className="space-y-2">
                        {overviewMedications.map((m, i) => (
                          <div key={i} className="flex items-center justify-between rounded-lg bg-white border border-slate-200 px-4 py-2.5 shadow-sm">
                            <div>
                              <p className="text-sm font-medium text-slate-900">{m.drug}</p>
                              <p className="text-xs text-slate-500">{m.dose} · {m.freq}</p>
                            </div>
                            <span className="text-xs text-slate-500">{m.duration}</span>
                          </div>
                        ))}
                      </div>
                    )
                  }
                </div>

                {/* Problem List */}
                <div>
                  <h3 className="text-xs font-semibold text-slate-600 uppercase tracking-wider mb-3 flex items-center gap-2">
                    <ClipboardList className="w-3.5 h-3.5" /> Problem List
                  </h3>
                  <div className="space-y-2">
                    {problems.map((p, i) => (
                      <div key={i} className="flex items-center justify-between rounded-lg bg-white border border-slate-200 px-4 py-2.5 shadow-sm">
                        <p className="text-sm text-slate-900">{p.name}</p>
                        <div className="flex items-center gap-3">
                          <span className="text-xs text-slate-500">Since {p.since}</span>
                          <span className={cn('text-xs font-medium', problemStatusColor(p.status))}>{p.status}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'SOAP Notes' && (
              <div className="space-y-5">
                {/* Previous Notes */}
                <div className="space-y-3">
                  {notes.map((note, i) => (
                    <div key={i} className="rounded-lg bg-white border border-slate-200 p-4 shadow-sm">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-xs font-medium text-emerald-700">{note.date}</span>
                        <span className="text-xs text-slate-500">{note.author}</span>
                      </div>
                      {[
                        { label: 'S', content: note.subjective },
                        { label: 'O', content: note.objective },
                        { label: 'A', content: note.assessment },
                        { label: 'P', content: note.plan },
                      ].map((s) => (
                        <div key={s.label} className="flex gap-2 mb-2 last:mb-0">
                          <span className="text-xs font-bold text-emerald-700 w-4 shrink-0">{s.label}:</span>
                          <p className="text-xs text-slate-700 whitespace-pre-line">{s.content}</p>
                        </div>
                      ))}
                    </div>
                  ))}
                </div>

                <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
                  <label className="flex items-center gap-2 text-sm font-medium text-slate-800">
                    <input
                      type="checkbox"
                      checked={communityFollowUpRequired}
                      onChange={(event) => setCommunityFollowUpRequired(event.target.checked)}
                      className="h-4 w-4 rounded border-slate-300"
                    />
                    Community follow-up required (send care plan to CHP app)
                  </label>
                  {communityFollowUpRequired && (
                    <textarea
                      value={communityFollowUpReason}
                      onChange={(event) => setCommunityFollowUpReason(event.target.value)}
                      className="mt-3 w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900"
                      rows={3}
                      placeholder="Follow-up reason for CHP team (optional)"
                    />
                  )}
                </div>

                {/* New Note */}
                <SOAPEditor 
                  patientName={selected.name}
                  initialData={{
                    subjective: soap.s,
                    objective: soap.o,
                    assessment: soap.a,
                    plan: soap.p
                  }}
                  onSave={async (data) => {
                    setSoap({ 
                      s: data.subjective, 
                      o: data.objective, 
                      a: data.assessment, 
                      p: data.plan 
                    });
                    try {
                      const response = await fetch('/api/medical/encounters/notes', {
                        method: 'POST',
                        headers: { 'content-type': 'application/json' },
                        body: JSON.stringify({
                          patientRef: selected.pid,
                          patientName: selected.name,
                          subjective: data.subjective,
                          objective: data.objective,
                          assessment: data.assessment,
                          plan: data.plan,
                        }),
                      });

                      if (!response.ok) {
                        throw new Error(`SOAP save failed (${response.status})`);
                      }

                      const saved = await response.json() as SOAPNote;
                      setSoapNotesState((prev) => ({
                        ...prev,
                        [selected.id]: [saved, ...(prev[selected.id] ?? [])],
                      }));
                      toast.success('SOAP note saved to clinical history');

                      if (communityFollowUpRequired) {
                        try {
                          await submitCommunityFollowUp({
                            patientRef: selected.pid,
                            patientName: selected.name,
                            carePlan: data.plan,
                            followUpReason: communityFollowUpReason.trim() || undefined,
                          });
                          setCommunityFollowUpRequired(false);
                          setCommunityFollowUpReason('');
                        } catch {
                          toast.error('SOAP saved, but CHP follow-up sync failed.');
                        }
                      }
                    } catch {
                      toast.error('Could not persist SOAP note. Please retry.');
                    }
                  }}
                />
              </div>
            )}

            {activeTab === 'Orders' && (
              <div className="space-y-4">
                <div className="flex gap-2 flex-wrap">
                  {[
                    { icon: <FlaskConical className="w-3.5 h-3.5" />, label: '+ Lab' },
                    { icon: <FileText className="w-3.5 h-3.5" />, label: '+ Imaging' },
                    { icon: <Syringe className="w-3.5 h-3.5" />, label: '+ Referral' },
                  ].map((b) => (
                    <button key={b.label} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white border border-slate-300 text-emerald-700 text-xs hover:bg-slate-50 transition-colors font-medium">
                      {b.icon} {b.label}
                    </button>
                  ))}
                </div>
                <div className="space-y-2">
                  {orders.length === 0
                    ? <p className="text-sm text-slate-500">No orders for this patient</p>
                    : orders.map((o) => (
                      <div key={o.id} className="flex items-center justify-between rounded-lg bg-white border border-slate-200 px-4 py-3 shadow-sm">
                        <div>
                          <p className="text-sm font-medium text-slate-900">{o.test}</p>
                          <p className="text-xs text-slate-500">{o.type} · Ordered {o.ordered}</p>
                        </div>
                        <span className={cn('text-xs px-2 py-0.5 rounded-full', {
                          'bg-amber-100 text-amber-700': o.status === 'Pending',
                          'bg-blue-100 text-blue-700': o.status === 'Processing',
                          'bg-emerald-100 text-emerald-700': o.status === 'Completed',
                        })}>
                          {o.status}
                        </span>
                      </div>
                    ))
                  }
                </div>
              </div>
            )}

            {activeTab === 'Teleconsult' && (
              <div className="h-[600px]">
                <Teleconsultation 
                  roomId={`tele-${selected.id}`} 
                  patientName={selected.name}
                  patientContext={`PID: ${selected.pid}, Complaint: ${selected.complaint}`}
                  onAnalysisSync={handleAnalysisSync}
                />
              </div>
            )}

            {activeTab === 'Clinical AI' && (
              <div className="h-[700px]">
                <AIDiagnosticAssistant 
                  initialSymptoms={aiTriageContext?.symptoms || selected.complaint}
                  activeContext={aiTriageContext?.context || `PID: ${selected.pid}, Age: ${selected.age}, Sex: ${selected.sex}, FHIRObservations: ${fhirSummary?.observations?.length ?? 0}, FHIRMeds: ${fhirSummary?.medicationRequests?.length ?? 0}`}
                />
              </div>
            )}

            {activeTab === 'AI Scribe' && (
              <div className="h-[600px]">
                <AfyaScribePanel 
                  consultationId={`scribe-${selected.id}`}
                />
              </div>
            )}

            {activeTab === 'History' && (
              <div className="space-y-3">
                <p className="text-xs text-slate-600 uppercase tracking-wider font-semibold">Previous Visits</p>
                {[
                  { date: '10 Jan 2025', type: 'OPD', doc: 'Dr. Amina', dx: 'Hypertension review' },
                  { date: '18 Dec 2024', type: 'OPD', doc: 'Dr. Mwangi', dx: 'Chest pain evaluation' },
                  { date: '05 Nov 2024', type: 'Emergency', doc: 'Dr. Kamau', dx: 'Hypertensive urgency' },
                ].map((v, i) => (
                  <div key={i} className="flex items-center justify-between rounded-lg bg-white border border-slate-200 px-4 py-3 shadow-sm">
                    <div>
                      <p className="text-sm font-medium text-slate-900">{v.dx}</p>
                      <p className="text-xs text-slate-500">{v.doc} · {v.type}</p>
                    </div>
                    <span className="text-xs text-slate-500">{v.date}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <PatientDetailPanel 
        patient={detailedPatient}
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        onTriageDeepDive={handleTriageDeepDive}
      />

      <PatientRegistrationForm 
        open={registrationOpen}
        onClose={() => setRegistrationOpen(false)}
        onSuccess={(patient) => {
          toast.success('Patient Registered Successfully', {
            description: `${patient.name} has been added to the registry.`,
            icon: '✅'
          });
        }}
      />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { 
  User, 
  Bell, 
  Video, 
  FileText, 
  BrainCircuit, 
  Accessibility, 
  Languages, 
  Shield, 
  Lock,
  Save,
  RotateCcw,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useCurrentSettings } from '@/lib/settings';

type SettingsTab = 'profile' | 'notifications' | 'consultation' | 'prescription' | 'video' | 'ai' | 'accessibility' | 'language' | 'security' | 'privacy';

const TABS: Array<{ key: SettingsTab; label: string; icon: React.ReactNode }> = [
  { key: 'profile', label: 'Profile', icon: <User className="w-4 h-4" /> },
  { key: 'notifications', label: 'Notifications', icon: <Bell className="w-4 h-4" /> },
  { key: 'consultation', label: 'Consultation', icon: <Video className="w-4 h-4" /> },
  { key: 'prescription', label: 'E-Prescription', icon: <FileText className="w-4 h-4" /> },
  { key: 'video', label: 'Video', icon: <Video className="w-4 h-4" /> },
  { key: 'ai', label: 'AI Assistant', icon: <BrainCircuit className="w-4 h-4" /> },
  { key: 'accessibility', label: 'Accessibility', icon: <Accessibility className="w-4 h-4" /> },
  { key: 'language', label: 'Language', icon: <Languages className="w-4 h-4" /> },
  { key: 'security', label: 'Security', icon: <Shield className="w-4 h-4" /> },
  { key: 'privacy', label: 'Privacy', icon: <Lock className="w-4 h-4" /> },
];

export default function DoctorSettingsPage() {
  const [activeTab, setActiveTab] = useState<SettingsTab>('profile');
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  
  const { settings, updateSettings, isLoading, reset } = useCurrentSettings('doctor');

  const handleSave = async () => {
    setSaveStatus('saving');
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSaveStatus('saved');
      setHasUnsavedChanges(false);
      setTimeout(() => setSaveStatus('idle'), 3000);
    } catch {
      setSaveStatus('error');
    }
  };

  const handleReset = () => {
    reset();
    setHasUnsavedChanges(false);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'profile':
        return <ProfileSettings settings={settings.profile} onChange={(data) => updateSettings({ profile: data })} />;
      case 'notifications':
        return <NotificationSettings settings={settings.notifications} onChange={(data) => updateSettings({ notifications: data })} />;
      case 'consultation':
        return <ConsultationSettings settings={settings.consultation} onChange={(data) => updateSettings({ consultation: data })} />;
      case 'prescription':
        return <PrescriptionSettings settings={settings.prescription} onChange={(data) => updateSettings({ prescription: data })} />;
      case 'video':
        return <VideoSettings settings={settings.video} onChange={(data) => updateSettings({ video: data })} />;
      case 'ai':
        return <AISettings settings={settings.aiAssistant} onChange={(data) => updateSettings({ aiAssistant: data })} />;
      case 'accessibility':
        return <AccessibilitySettings settings={settings.accessibility} onChange={(data) => updateSettings({ accessibility: data })} />;
      case 'language':
        return <LanguageSettings settings={settings.language} onChange={(data) => updateSettings({ language: data })} />;
      case 'security':
        return <SecuritySettings settings={settings.security} onChange={(data) => updateSettings({ security: data })} />;
      case 'privacy':
        return <PrivacySettings settings={settings.privacy} onChange={(data) => updateSettings({ privacy: data })} />;
      default:
        return null;
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-slate-500 animate-pulse">Loading settings...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Settings</h1>
          <p className="text-sm text-slate-500 mt-1">
            Manage your account preferences and system configuration
          </p>
        </div>
        <div className="flex items-center gap-3">
          {hasUnsavedChanges && (
            <div className="flex items-center gap-2 text-amber-600 text-sm">
              <AlertCircle className="w-4 h-4" />
              Unsaved changes
            </div>
          )}
          <button
            onClick={handleReset}
            className="flex items-center gap-2 px-4 py-2 text-sm text-slate-600 hover:text-slate-900 border border-slate-200 rounded-lg hover:bg-slate-50 transition-colors"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
          <button
            onClick={handleSave}
            disabled={saveStatus === 'saving' || !hasUnsavedChanges}
            className={cn(
              'flex items-center gap-2 px-4 py-2 text-sm text-white rounded-lg transition-colors',
              saveStatus === 'saving' 
                ? 'bg-slate-400 cursor-not-allowed' 
                : saveStatus === 'saved'
                ? 'bg-emerald-500'
                : 'bg-emerald-600 hover:bg-emerald-500'
            )}
          >
            {saveStatus === 'saving' ? (
              <>
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                Saving...
              </>
            ) : saveStatus === 'saved' ? (
              <>
                <CheckCircle2 className="w-4 h-4" />
                Saved
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                Save Changes
              </>
            )}
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex flex-wrap gap-2 border-b border-slate-200 pb-2">
        {TABS.map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={cn(
              'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
              activeTab === tab.key
                ? 'bg-emerald-100 text-emerald-700'
                : 'text-slate-600 hover:bg-slate-100'
            )}
          >
            {tab.icon}
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="bg-white rounded-xl border border-slate-200 p-6">
        {renderTabContent()}
      </div>
    </div>
  );
}

