        <ToggleOption
          label="Login Notifications"
          description="Get notified of new login activity"
          enabled={settings.loginNotifications}
          onChange={() => onChange({ ...settings, loginNotifications: !settings.loginNotifications })}
        />
      </div>
      
      <div className="mt-6 p-4 bg-slate-50 rounded-lg border border-slate-200">
        <h3 className="text-sm font-semibold text-slate-900 mb-3">Trusted Devices</h3>
        <p className="text-sm text-slate-500 mb-3">
          These devices are trusted and won't require 2FA for login.
        </p>
        <div className="space-y-2">
          <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-slate-200">
            <div>
              <p className="text-sm font-medium text-slate-900">Current Device</p>
              <p className="text-xs text-slate-500">Last used: Just now</p>
            </div>
            <span className="text-xs text-emerald-600 font-medium">Active</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// Privacy Settings Component
 
function PrivacySettings({ settings, onChange }: { settings: any; onChange: (data: any) => void }) {
  return (
    <div className="space-y-6">
      <h2 className="text-lg font-semibold text-slate-900">Privacy Settings</h2>
      
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">Profile Visibility</label>
          <select
            value={settings.profileVisibility}
            onChange={(e) => onChange({ ...settings, profileVisibility: e.target.value })}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500"
          >
            <option value="private">Private (Only me)</option>
            <option value="colleagues">Colleagues (My organization)</option>
            <option value="public">Public (Anyone)</option>
          </select>
        </div>
      </div>
      
      <div className="space-y-4 pt-4">
        <ToggleOption
          label="Show Online Status"
          description="Allow others to see when you're online"
          enabled={settings.showOnlineStatus}
          onChange={() => onChange({ ...settings, showOnlineStatus: !settings.showOnlineStatus })}
        />
        
        <ToggleOption
          label="Data Sharing for Research"
          description="Allow anonymized data to be used for medical research"
          enabled={settings.dataSharing}
          onChange={() => onChange({ ...settings, dataSharing: !settings.dataSharing })}
        />
        
        <ToggleOption
          label="Analytics Opt-Out"
          description="Opt out of usage analytics collection"
          enabled={settings.analyticsOptOut}
          onChange={() => onChange({ ...settings, analyticsOptOut: !settings.analyticsOptOut })}
        />
        
        <ToggleOption
          label="Marketing Opt-Out"
          description="Opt out of marketing communications"
          enabled={settings.marketingOptOut}
          onChange={() => onChange({ ...settings, marketingOptOut: !settings.marketingOptOut })}
        />
      </div>
    </div>
  );
}

// Toggle Option Component
function ToggleOption({ label, description, enabled, onChange }: { 
  label: string; 
  description: string; 
  enabled: boolean; 
  onChange: () => void;
}) {
  return (
    <div className="flex items-center justify-between py-3 border-b border-slate-100">
      <div>
        <p className="font-medium text-slate-900">{label}</p>
        <p className="text-sm text-slate-500">{description}</p>
      </div>
      <button
        onClick={onChange}
        className={cn(
          'relative w-11 h-6 rounded-full transition-colors',
          enabled ? 'bg-emerald-500' : 'bg-slate-200'
        )}
      >
        <span
          className={cn(
            'absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform',
            enabled ? 'translate-x-5' : 'translate-x-0'
          )}
        />
      </button>
    </div>
  );
}

'use client';

import { useState } from 'react';
import {
  Plus, Eye, Printer, X, Trash2, DollarSign, Phone, CreditCard, FileText, Send, CheckCircle, Loader2, Clock, ShieldCheck
} from 'lucide-react';
import SHIFClaimsPanel from '@/components/portal/billing/SHIFClaimsPanel';
import { cn } from '@/lib/utils';

const ACCENT = '#F59E0B';
const MPESA_GREEN = '#00A650';
const VISA_BLUE = '#1A1F71';
const INSURANCE_BLUE = '#2563EB';

type InvoiceStatus = 'Paid' | 'Pending' | 'Partial';

interface InvoiceRow {
  id: string;
  patient: string;
  date: string;
  services: string;
  amount: number;
  paid: number;
  status: InvoiceStatus;
}

interface LineItem {
  id: number;
  description: string;
  qty: number;
  unitPrice: number;
}

const INITIAL_INVOICES: InvoiceRow[] = [
