  { id: 'INV-0892', patient: 'Brian Omondi', date: 'Today 08:05', services: 'ECG, Blood Tests', amount: 4800, paid: 2400, status: 'Partial' },
  { id: 'INV-0893', patient: 'Fatuma Hassan', date: 'Today 08:22', services: 'Consultation, Drugs', amount: 2200, paid: 0, status: 'Pending' },
  { id: 'INV-0894', patient: 'James Kipchoge', date: 'Today 08:35', services: 'Emergency, X-Ray', amount: 9500, paid: 9500, status: 'Paid' },
  { id: 'INV-0895', patient: 'Achieng Otieno', date: 'Today 09:00', services: 'ANC Visit, Lab', amount: 3400, paid: 1700, status: 'Partial' },
  { id: 'INV-0896', patient: 'Mohamed Abdi', date: 'Today 09:12', services: 'Hypertension Review', amount: 1800, paid: 0, status: 'Pending' },
  { id: 'INV-0897', patient: 'Nyambura Gicheru', date: 'Today 09:30', services: 'Consultation, Drugs', amount: 1200, paid: 1200, status: 'Paid' },
  { id: 'INV-0898', patient: 'David Muthama', date: 'Today 09:45', services: 'Vaccination', amount: 800, paid: 800, status: 'Paid' },
];

const STATUS_STYLES: Record<InvoiceStatus, string> = {
  Paid: 'bg-emerald-100 text-emerald-700 border border-emerald-200',
  Pending: 'bg-amber-100 text-amber-700 border border-amber-200',
  Partial: 'bg-orange-100 text-orange-700 border border-orange-200',
};

const INITIAL_ITEMS: LineItem[] = [
  { id: 1, description: '', qty: 1, unitPrice: 0 },
];

function fmt(n: number): string {
  return `KES ${n.toLocaleString('en-KE')}`;
}

export default function BillingPage() {
  const [invoices, setInvoices] = useState<InvoiceRow[]>(INITIAL_INVOICES);
  const [showInvoiceForm, setShowInvoiceForm] = useState(false);
  const [patientSearch, setPatientSearch] = useState('');
  const [lineItems, setLineItems] = useState<LineItem[]>(INITIAL_ITEMS);
  const [paymentMethod, setPaymentMethod] = useState('Cash');
  const [paymentAmount, setPaymentAmount] = useState('');

  // M-Pesa specific state
  const [mpesaPhone, setMpesaPhone] = useState('');
  const [mpesaPromptStatus, setMpesaPromptStatus] = useState<'idle' | 'sending' | 'sent' | 'failed'>('idle');

  // Card specific state
  const [cardNumber, setCardNumber] = useState('');
  const [cardExpiry, setCardExpiry] = useState('');
  const [cardCVV, setCardCVV] = useState('');

  // Insurance specific state
  const [insuranceProvider, setInsuranceProvider] = useState('');
  const [policyNumber, setPolicyNumber] = useState('');
  const [showClaimsPanel, setShowClaimsPanel] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const total = lineItems.reduce((sum, i) => sum + i.qty * i.unitPrice, 0);

  function addLine() {
    setLineItems((prev) => [...prev, { id: Date.now(), description: '', qty: 1, unitPrice: 0 }]);
  }

  function removeLine(id: number) {
    setLineItems((prev) => prev.filter((i) => i.id !== id));
  }

  function updateLine(id: number, field: keyof Omit<LineItem, 'id'>, value: string) {
    setLineItems((prev) =>
      prev.map((i) =>
        i.id === id
          ? { ...i, [field]: field === 'description' ? value : Number(value) }
          : i,
      ),
    );
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitError(null);
    setSubmitting(true);
    try {
      const idempotencyKey = crypto.randomUUID();
      const res = await fetch('/api/billing/invoices', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-idempotency-key': idempotencyKey,
        },
        body: JSON.stringify({
          patient: patientSearch,
          lineItems: lineItems.filter((item) => item.description.trim().length > 0),
          paymentMethod,
          paymentAmount: Number(paymentAmount || 0),
        }),
      });
      const payload = await res.json();
      if (!res.ok) {
        throw new Error(payload?.error ?? 'Failed to create invoice.');
      }

      const invoice = payload.invoice as InvoiceRow;
      setInvoices((prev) => [invoice, ...prev]);
      setShowInvoiceForm(false);
      setLineItems(INITIAL_ITEMS);
      setPatientSearch('');
      setPaymentAmount('');
    } catch (err) {
      setSubmitError(err instanceof Error ? err.message : 'Failed to create invoice.');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Billing & Payments</h1>
          <p className="text-slate-500 text-sm mt-0.5">Manage invoices and collections</p>
        </div>
        <button
          onClick={() => setShowInvoiceForm((v) => !v)}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl font-semibold text-sm text-ink transition-opacity hover:opacity-90"
          style={{ backgroundColor: ACCENT }}
        >
          <Plus className="w-4 h-4" />
          New Invoice
        </button>
      </div>

      {/* Summary Strip */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Total Today', value: 'KES 84,200', color: ACCENT },
          { label: 'Cash', value: 'KES 32,400', color: '#10B981' },
          { label: 'M-Pesa', value: 'KES 41,800', color: '#8B5CF6' },
          { label: 'Insurance', value: 'KES 10,000', color: '#3B82F6' },
        ].map((s) => (
          <div 
            key={s.label} 
            className={cn(
              "bg-white border border-slate-200 rounded-2xl p-4 shadow-sm cursor-pointer transition-all hover:bg-slate-50 relative group",
              s.label === 'Insurance' && "border-blue-200"
            )}
            onClick={() => s.label === 'Insurance' && setShowClaimsPanel(true)}
          >
            <p className="text-slate-500 text-xs uppercase tracking-wide mb-1">{s.label}</p>
            <p className="text-xl font-bold" style={{ color: s.color }}>{s.value}</p>
            {s.label === 'Insurance' && (
              <div className="absolute top-2 right-2 p-1 bg-blue-100 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity">
                <ShieldCheck className="w-3 h-3 text-blue-600" />
              </div>
            )}
          </div>
        ))}
      </div>

      {/* New Invoice Form */}
      {showInvoiceForm && (
        <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
          <div className="px-6 py-4 border-b border-slate-200 flex items-center justify-between">
            <h2 className="text-slate-900 font-semibold">New Invoice</h2>
            <button
              onClick={() => setShowInvoiceForm(false)}
              className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-500 hover:text-slate-800"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
          <form onSubmit={handleSubmit} className="p-6 space-y-5">
            {submitError && (
              <div className="rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
                {submitError}
              </div>
            )}
            {/* Patient search */}
            <div className="space-y-1">
              <label className="text-xs text-slate-500">Patient *</label>
              <input
                value={patientSearch}
                onChange={(e) => setPatientSearch(e.target.value)}
                placeholder="Search patient by name or token..."
                required
                className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-amber-500/30 focus:border-amber-400"
              />
            </div>

            {/* Line items */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="text-xs text-slate-500 uppercase tracking-wide font-semibold">Line Items</label>
                <button
                  type="button"
                  onClick={addLine}
                  className="flex items-center gap-1 text-xs font-medium px-2.5 py-1 rounded-lg border border-slate-300 text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors"
                >
                  <Plus className="w-3 h-3" /> Add Row
                </button>
              </div>
              <div className="space-y-2">
                <div className="grid grid-cols-12 gap-2 text-xs text-slate-500 px-1">
                  <span className="col-span-6">Description</span>
                  <span className="col-span-2">Qty</span>
                  <span className="col-span-2">Unit Price</span>
                  <span className="col-span-1">Total</span>
                  <span className="col-span-1" />
                </div>
                {lineItems.map((item) => (
                  <div key={item.id} className="grid grid-cols-12 gap-2 items-center">
                    <input
                      value={item.description}
                      onChange={(e) => updateLine(item.id, 'description', e.target.value)}
                      placeholder="Service description"
                      className="col-span-6 bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-amber-500/30 focus:border-amber-400"
                    />
                    <input
                      type="number"
                      min={1}
                      value={item.qty}
                      onChange={(e) => updateLine(item.id, 'qty', e.target.value)}
                      className="col-span-2 bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-amber-500/30 focus:border-amber-400"
                    />
                    <input
                      type="number"
                      min={0}
                      value={item.unitPrice}
                      onChange={(e) => updateLine(item.id, 'unitPrice', e.target.value)}
                      className="col-span-2 bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-amber-500/30 focus:border-amber-400"
                    />
                    <span className="col-span-1 text-sm text-slate-600">
                      {(item.qty * item.unitPrice).toLocaleString()}
                    </span>
                    <button
                      type="button"
                      onClick={() => removeLine(item.id)}
                      className="col-span-1 p-1.5 rounded-lg hover:bg-rose-100 text-slate-500 hover:text-rose-700 transition-colors"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
                <div className="flex justify-end pt-2 border-t border-slate-200">
                  <div className="text-right">
                    <p className="text-xs text-slate-500">Total</p>
                    <p className="text-lg font-bold" style={{ color: ACCENT }}>{fmt(total)}</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Payment Method Selection */}
            <div className="space-y-3">
              <label className="text-xs text-slate-500">Payment Method</label>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                {[
                  { id: 'Cash', icon: <DollarSign className="w-4 h-4" />, color: ACCENT, active: false },
                  { id: 'M-Pesa', icon: <Phone className="w-4 h-4" />, color: MPESA_GREEN, active: false },
                  { id: 'Card/Visa', icon: <CreditCard className="w-4 h-4" />, color: VISA_BLUE, active: false },
                  { id: 'Insurance', icon: <FileText className="w-4 h-4" />, color: INSURANCE_BLUE, active: false },
                ].map((method) => (
                  <button
                    key={method.id}
                    type="button"
                    disabled={!method.active}
                    onClick={() => setPaymentMethod(method.id)}
                    className={cn(
                      'flex flex-col items-center justify-center gap-1 px-3 py-2.5 rounded-xl border-2 transition-all text-sm font-medium relative',
                      paymentMethod === method.id
                        ? 'border-transparent text-white shadow-md'
                        : 'border-slate-200 text-slate-700 hover:border-slate-300',
                      !method.active && 'opacity-50 grayscale cursor-not-allowed'
                    )}
                    style={{ backgroundColor: paymentMethod === method.id ? method.color : undefined }}
                  >
                    <div className="flex items-center gap-2">
                      {method.icon}
                      {method.id}
                    </div>
                    {!method.active && (
                      <span className="text-[9px] font-bold uppercase tracking-tighter text-rose-600 bg-rose-50 px-1.5 rounded-md border border-rose-200 absolute -top-2 -right-1">
                        Inactive
                      </span>
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* Amount Paid */}
            <div className="space-y-1">
              <label className="text-xs text-slate-500">Amount Paid (KES)</label>
              <input
                type="number"
                min={0}
                value={paymentAmount}
                onChange={(e) => setPaymentAmount(e.target.value)}
                placeholder="0"
                className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-amber-500/30 focus:border-amber-400"
              />
            </div>

            {/* M-Pesa Payment Section - DEACTIVATED */}
            {paymentMethod === 'M-Pesa' && false && (
              <div className="border border-emerald-200 bg-emerald-50 rounded-xl p-4 space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold text-emerald-800 flex items-center gap-2">
                    <Phone className="w-4 h-4" /> M-Pesa Payment
                  </h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs text-slate-500">Patient Phone Number</label>
                    <input
                      type="tel"
                      value={mpesaPhone}
                      onChange={(e) => setMpesaPhone(e.target.value)}
                      placeholder="2547XXXXXXXX"
                      className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-400"
                    />
                  </div>
                  <div className="flex items-end">
                    <button
                      type="button"
                      onClick={() => {
                        setMpesaPromptStatus('sending');
                        setTimeout(() => setMpesaPromptStatus('sent'), 2000);
                      }}
                      disabled={!mpesaPhone || mpesaPromptStatus === 'sending'}
                      className="w-full flex items-center justify-center gap-2 px-4 py-2 rounded-xl font-medium text-white transition-opacity disabled:opacity-50"
                      style={{ backgroundColor: MPESA_GREEN }}
                    >
                      {mpesaPromptStatus === 'sending' ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : mpesaPromptStatus === 'sent' ? (
                        <CheckCircle className="w-4 h-4" />
                      ) : (
                        <Send className="w-4 h-4" />
                      )}
                      {mpesaPromptStatus === 'sending' ? 'Sending Prompt...' : 
                       mpesaPromptStatus === 'sent' ? 'Prompt Sent ✓' : 'Send M-Pesa Prompt'}
                    </button>
                  </div>
                </div>

                {mpesaPromptStatus === 'sent' && (
                  <div className="flex items-center gap-2 p-3 bg-white rounded-lg border border-emerald-200">
                    <CheckCircle className="w-5 h-5 text-emerald-600" />
                    <p className="text-sm text-emerald-800">
                      M-Pesa STK push sent to {mpesaPhone}. Patient will receive a payment prompt on their phone.
                    </p>
                  </div>
                )}
              </div>
            )}

            {/* Card/Visa Payment Section - DEACTIVATED */}
            {paymentMethod === 'Card/Visa' && false && (
              <div className="border border-blue-200 bg-blue-50 rounded-xl p-4 space-y-4">
                <h3 className="font-semibold text-blue-800 flex items-center gap-2">
                  <CreditCard className="w-4 h-4" /> Card / Visa Payment
                </h3>

                <div className="space-y-1">
                  <label className="text-xs text-slate-500">Card Number</label>
                  <input
                    type="text"
                    value={cardNumber}
                    onChange={(e) => setCardNumber(e.target.value)}
                    placeholder="1234 5678 9012 3456"
                    maxLength={19}
                    className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-400"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs text-slate-500">Expiry Date</label>
                    <input
                      type="text"
                      value={cardExpiry}
                      onChange={(e) => setCardExpiry(e.target.value)}
                      placeholder="MM/YY"
                      maxLength={5}
                      className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-400"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs text-slate-500">CVV</label>
                    <input
                      type="password"
                      value={cardCVV}
                      onChange={(e) => setCardCVV(e.target.value)}
                      placeholder="123"
                      maxLength={4}
                      className="w-full bg-white border border-slate-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-400"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Insurance Claims Section - DEACTIVATED */}
            {paymentMethod === 'Insurance' && false && (
              <div className="border border-blue-200 bg-blue-50 rounded-xl p-4 space-y-4">
                <h3 className="font-semibold text-blue-800 flex items-center gap-2">
                  <FileText className="w-4 h-4" /> Insurance Claim Management
