                    <ShieldCheck className="w-4 h-4 text-emerald-500" />
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">End-to-End Encrypted Tunnel Active</span>
                </div>
            </motion.div>
        );
