        <div className="relative h-full flex flex-col p-6 space-y-6 overflow-hidden bg-[#080F0C] rounded-[2.5rem] border border-white/5">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center">
                        <Video className="w-6 h-6 text-blue-500" />
                    </div>
                    <div>
                        <button 
                            onClick={onViewPatient}
                            className="text-xl font-serif italic text-white hover:text-blue-400 transition-colors text-left"
                        >
                            {patientName ?? 'Standard Consultation'}
