                        <div className="flex items-center gap-2 mt-1">
                            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">{activeCallMode} Link Established</span>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-3 px-4 py-2 bg-white/5 rounded-2xl border border-white/10">
                    <Clock className="w-4 h-4 text-blue-400" />
                    <span className="text-xs font-mono text-white tracking-widest leading-none">{elapsedMinutes}m Standard Session</span>
