            {/* The "Virtual Room" Frame */}
            <div className="flex-1 relative bg-white/[0.02] rounded-[2.5rem] border border-white/5 overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-emerald-500/5 pointer-events-none" />

                <div className="absolute inset-0 flex flex-col items-center justify-center p-12 text-center space-y-8">
