'use client';

import { useState, useRef, useCallback } from 'react';
import { 
  Paperclip, 
  Image as ImageIcon, 
  Mic, 
  Send, 
  X, 
  FileText, 
  Square,
  Loader2
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface MultiModalPayload {
  text: string;
  files: File[];
  audio?: Blob;
}

interface MultiModalInputProps {
  onSend: (payload: MultiModalPayload) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

export function MultiModalInput({
  onSend,
  placeholder = "Type a message or record audio...",
  disabled = false,
  className
}: MultiModalInputProps) {
  const [text, setText] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const handleSend = useCallback(() => {
    if (!text.trim() && files.length === 0) return;

    onSend({
      text: text.trim(),
      files,
    });

    setText('');
    setFiles([]);
  }, [text, files, onSend]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(prev => [...prev, ...Array.from(e.target.files!)]);
    }
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      const chunks: Blob[] = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = () => {
        const audioBlob = new Blob(chunks, { type: 'audio/webm' });
        onSend({ text: '[Audio Message]', files: [], audio: audioBlob });
        stream.getTracks().forEach(t => t.stop());
      };

      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error('Failed to start recording', err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className={cn("flex flex-col gap-2 p-2 bg-white/5 rounded-3xl border border-white/10 shadow-inner group focus-within:border-primary/30 transition-all", className)}>
      {/* Previews */}
      <AnimatePresence>
        {files.length > 0 && (
          <motion.div 
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="flex flex-wrap gap-2 px-3 pt-2"
          >
            {files.map((file, i) => (
              <motion.div 
                key={`${file.name}-${i}`}
                initial={{ scale: 0.8, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="relative group/file"
              >
                <div className="w-16 h-16 rounded-xl bg-white/10 border border-white/10 flex items-center justify-center overflow-hidden">
                  {file.type.startsWith('image/') ? (
                    <img 
                      src={URL.createObjectURL(file)} 
                      alt="preview" 
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <FileText className="w-6 h-6 text-white/40" />
                  )}
                </div>
                <button 
                  onClick={() => removeFile(i)}
                  className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 rounded-full flex items-center justify-center opacity-0 group-hover/file:opacity-100 transition-opacity"
                >
                  <X className="w-3 h-3 text-white" />
                </button>
              </motion.div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex items-end gap-2 px-2 py-1">
        {isRecording ? (
          <div className="flex-1 flex items-center gap-3 px-4 py-3 bg-rose-500/10 rounded-2xl border border-rose-500/20">
            <div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse" />
            <span className="text-xs font-mono font-bold text-rose-500">Recording... {formatTime(recordingTime)}</span>
            <button 
              onClick={stopRecording}
              className="ml-auto w-8 h-8 rounded-full bg-rose-500 flex items-center justify-center hover:bg-rose-600 transition-colors"
            >
              <Square className="w-3.5 h-3.5 text-white" />
            </button>
          </div>
        ) : (
          <>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              multiple 
              onChange={handleFileChange}
              accept="image/*,.pdf,.doc,.docx"
            />

            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="p-3 text-white/40 hover:text-white hover:bg-white/5 rounded-2xl transition-all active:scale-95"
              title="Attach files"
            >
              <Paperclip className="w-5 h-5" />
            </button>

            <div className="flex-1 relative">
              <textarea
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                disabled={disabled}
                placeholder={placeholder}
                rows={1}
                className="w-full bg-transparent border-none text-sm text-white placeholder:text-white/20 py-3 px-1 outline-none resize-none max-h-32 custom-scrollbar font-medium"
              />
            </div>

            <div className="flex items-center gap-1 self-center">
              <button 
                type="button"
                onClick={startRecording}
                className="p-3 text-white/40 hover:text-rose-400 hover:bg-rose-500/5 rounded-2xl transition-all active:scale-95"
                title="Record audio"
              >
                <Mic className="w-5 h-5" />
              </button>

              <button 
                type="button"
                onClick={handleSend}
                disabled={disabled || (!text.trim() && files.length === 0)}
                className="p-3 bg-primary text-white rounded-2xl transition-all active:scale-95 disabled:opacity-30 disabled:grayscale disabled:scale-100 hover:shadow-lg hover:shadow-primary/20"
                style={{ background: '#2563EB' }}
              >
                <Send className="w-5 h-5" />
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useRef, useCallback, useEffect } from 'react';
import {
  Video,
  Phone,
  MessageSquare,
  ExternalLink,
  Copy,
  CheckCircle2,
  Loader2,
  Sparkles,
  BrainCircuit,
  Mic,
  Clock,
  ArrowUpRight,
  Activity,
  User,
  LineChart,
  ClipboardList,
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';
import { ModeButton } from './ModeButton';
import { AIScribePanel } from './AIScribePanel';
import { MultiModalInput } from '../common/MultiModalInput';
import logger from '@/lib/logger';
import { readResponseErrorMessage } from '@/lib/fetch-error';
import type { 
  TeleconsultationProps, 
  CallMode, 
  ConnectionStatus, 
  TranscriptEntry, 
  ClinicalAnalysis 
} from './types';

export function ConsultationStudio({ 
  roomId, 
  patientName, 
  patientContext,
  consultationType = 'virtual'
}: TeleconsultationProps) {
  const [activeCallMode, setActiveCallMode] = useState<CallMode>(consultationType === 'physical' ? 'voice' : 'video');
  const [isCallActive, setIsCallActive] = useState(consultationType === 'physical'); // Auto-active for physical
  const [meetCode, setMeetCode] = useState<string | null>(null);
  const [meetUrl, setMeetUrl] = useState<string | null>(null);
  const [meetProvider, setMeetProvider] = useState<string>('');
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('idle');
  const [copied, setCopied] = useState(false);
  const [callStartedAt, setCallStartedAt] = useState<Date | null>(null);

  const [transcripts, setTranscripts] = useState<TranscriptEntry[]>([]);
  const [liveTranscript, setLiveTranscript] = useState('');
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<ClinicalAnalysis | null>(null);
  const [analysisProvider, setAnalysisProvider] = useState('');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioStreamRef = useRef<MediaStream | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const elapsedMinutes = callStartedAt ? Math.floor((Date.now() - callStartedAt.getTime()) / 60000) : 0;

  const createMeeting = useCallback(async () => {
    setConnectionStatus('creating');
    try {
      const res = await fetch('/api/teleconsultation/meetings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          patientName: patientName ?? 'Patient',
          appointmentId: roomId,
          description: 'Teleconsultation session',
        }),
      });

      if (!res.ok) {
        const message = await readResponseErrorMessage(res);
        logger.warn('Teleconsultation meeting creation failed', { status: res.status, message });
        setConnectionStatus('failed');
        return;
      }

      const data = await res.json();
      setMeetCode(data.meetingCode);
      setMeetUrl(data.meetUrl);
      setMeetProvider(data.provider);
      setConnectionStatus('ready');
      setIsCallActive(true);
    } catch (error) {
      logger.error('Teleconsultation meeting creation threw', {
        error: error instanceof Error ? error.message : String(error),
      });
      setConnectionStatus('failed');
    }
  }, [patientName, roomId]);

  const startCall = useCallback(async () => {
    await createMeeting();
  }, [createMeeting]);

  const openMeetInNewTab = useCallback(() => {
    if (meetUrl) {
      const opened = window.open(meetUrl, '_blank', 'noopener,noreferrer');
      if (opened) opened.opener = null;
    }
  }, [meetUrl]);

  const blobToBase64 = useCallback((blob: Blob): Promise<string> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
      reader.readAsDataURL(blob);
    });
  }, []);

  const transcribeAudio = useCallback(async (audioBase64: string, encoding: string) => {
    try {
      const res = await fetch('/api/teleconsultation/transcribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ audio: audioBase64, encoding: encoding === 'WEBM_OPUS' ? 'webm_opus' : 'pcm16' }),
      });
      if (!res.ok) {
        const message = await readResponseErrorMessage(res);
        logger.warn('Teleconsultation transcription failed', { status: res.status, message });
        return;
      }
      const data = await res.json();
      if (data.transcript) {
        setLiveTranscript(prev => prev + ' ' + data.transcript);
        setTranscripts(prev => [...prev, {
          id: `tr-${Date.now()}`,
          text: data.transcript,
          timestamp: new Date(),
          confidence: data.confidence ?? 0,
          provider: data.provider,
        }]);
      }
    } catch (error) {
      logger.debug('Teleconsultation transcription threw', {
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }, []);

  const startBrowserSpeechRecognition = useCallback(() => {
    const SpeechRecognition = (globalThis as any).SpeechRecognition || (globalThis as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;

    const recognition = new (SpeechRecognition as any)();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onresult = (event: any) => {
      let interim = '';
      let final = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const t = event.results[i][0].transcript as string;
        if (event.results[i].isFinal) final += t;
        else interim += t;
      }
      setLiveTranscript(prev => prev + ' ' + interim);
      if (final) {
        setTranscripts(prev => [...prev, {
          id: `tr-${Date.now()}`,
          text: final,
          timestamp: new Date(),
          confidence: event.results[event.results.length - 1][0].confidence as number,
          provider: 'browser-speech',
        }]);
      }
    };

    recognition.start();
    setIsTranscribing(true);
  }, []);

  const startAudioCapture = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioStreamRef.current = stream;

      const recorder = new MediaRecorder(stream, { mimeType: 'audio/webm;codecs=opus' });
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        audioChunksRef.current = [];

        if (blob.size > 1000) {
          const base64 = await blobToBase64(blob);
          void transcribeAudio(base64, 'WEBM_OPUS');
        }

        if (isCallActive && mediaRecorderRef.current?.state === 'inactive') {
          mediaRecorderRef.current.start(5000);
        }
      };

      recorder.start(5000);
      setIsTranscribing(true);
    } catch {
      startBrowserSpeechRecognition();
    }
  }, [isCallActive, startBrowserSpeechRecognition, transcribeAudio, blobToBase64]);

  const stopAudioCapture = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    if (audioStreamRef.current) {
      audioStreamRef.current.getTracks().forEach(t => t.stop());
    }
    setIsTranscribing(false);
  }, []);

  const handleAnalyze = useCallback(async () => {
    const fullTranscript = transcripts.map(t => t.text).join(' ') + ' ' + liveTranscript;
    if (!fullTranscript.trim()) return;

    setIsAnalyzing(true);
    setAnalysis(null);

    try {
      const res = await fetch('/api/teleconsultation/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          transcript: fullTranscript.trim(),
          patientContext: patientContext ?? '',
        }),
      });
      if (!res.ok) {
        const message = await readResponseErrorMessage(res);
        logger.warn('Teleconsultation analysis failed', { status: res.status, message });
        return;
      }
      const data = await res.json();
      if (data.analysis) {
        setAnalysis(data.analysis);
        setAnalysisProvider(data.provider);
      }
    } catch (error) {
      logger.debug('Teleconsultation analysis threw', {
        error: error instanceof Error ? error.message : String(error),
      });
    } finally {
      setIsAnalyzing(false);
    }
  }, [transcripts, liveTranscript, patientContext]);

  const endCall = useCallback(() => {
    stopAudioCapture();
    setMeetCode(null);
    setMeetUrl(null);
    setIsCallActive(false);
    setCallStartedAt(null);
    setConnectionStatus('idle');
    setLiveTranscript('');
    setAnalysis(null);
  }, [stopAudioCapture]);

  useEffect(() => {
    if (isCallActive && connectionStatus === 'ready') {
      setCallStartedAt(new Date());
      if (activeCallMode !== 'text') {
        void startAudioCapture();
      }
    }
    return () => {
      if (!isCallActive) stopAudioCapture();
    };
  }, [isCallActive, connectionStatus, activeCallMode, startAudioCapture, stopAudioCapture]);

  const copyMeetLink = useCallback(() => {
    if (meetUrl) {
      navigator.clipboard.writeText(meetUrl).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  }, [meetUrl]);

  if (!isCallActive) {
    return (
