'use client';

import { useState, useEffect } from 'react';
import { 
  QrCode, 
  Smartphone, 
  Settings, 
  CheckCircle2, 
  Zap, 
  AlertCircle,
  Link,
  SmartphoneNfc,
  Camera
} from 'lucide-react';
import { cn } from '@/lib/utils';

export function BarcodeScanner() {
  const [isPaired, setIsPaired] = useState(false);
  const [scanStream, setScanStream] = useState<string[]>([]);

  // Simulate incoming scans
  useEffect(() => {
    if (isPaired) {
        const interval = setInterval(() => {
            const mockScans = ['600123456789', '501101234567', '400840012345'];
            const randomScan = mockScans[Math.floor(Math.random() * mockScans.length)];
            setScanStream(prev => [randomScan, ...prev].slice(0, 5));
        }, 8000);
        return () => clearInterval(interval);
    }
    return undefined;
  }, [isPaired]);

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 shadow-sm">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h3 className="text-xl font-serif font-bold text-charcoal tracking-tight">Scanner Integration</h3>
          <p className="text-[10px] font-black font-mono text-slate-400 uppercase tracking-widest">Connect External Handheld or Phone</p>
        </div>
        <div className={cn(
            "px-4 py-1.5 rounded-full flex items-center gap-2 border transition-all",
            isPaired ? "bg-emerald-50 border-emerald-100 text-emerald-600" : "bg-slate-50 border-slate-100 text-slate-400"
        )}>
            <div className={cn("w-1.5 h-1.5 rounded-full", isPaired ? "bg-emerald-500 animate-pulse" : "bg-slate-300")} />
            <span className="text-[9px] font-black uppercase tracking-widest">{isPaired ? 'Device Linked' : 'Offline'}</span>
        </div>
      </div>

      {!isPaired ? (
        <div className="flex flex-col items-center justify-center py-10 text-center">
            <div className="relative mb-6">
                <div className="absolute inset-0 bg-violet-500/10 blur-2xl rounded-full" />
                <div className="relative w-24 h-24 bg-white border-2 border-slate-100 rounded-3xl flex items-center justify-center shadow-inner">
                    <QrCode className="w-12 h-12 text-slate-200" />
                </div>
            </div>
            <h4 className="text-sm font-bold text-slate-900 mb-2">Pair Stock-Control Device</h4>
            <p className="text-[11px] text-slate-500 max-w-[240px] leading-relaxed mb-6">
                Scan the encrypted QR code with the AfyaHero Mobile app to use your phone as a precision barcode scanner.
            </p>
            <button 
                onClick={() => setIsPaired(true)}
                className="px-8 py-3 rounded-full bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest hover:bg-violet-700 transition-all shadow-xl shadow-violet-900/20"
            >
                Generate Pairing Key
            </button>
        </div>
      ) : (
        <div className="space-y-6">
            <div className="p-5 rounded-3xl bg-slate-50 border border-slate-100">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                        <Smartphone className="w-4 h-4 text-violet-600" />
                        <span className="text-xs font-bold text-slate-900">iPhone 15 Pro Max</span>
                    </div>
                    <button onClick={() => setIsPaired(false)} className="text-[9px] font-black text-rose-500 uppercase tracking-widest">Unpair</button>
                </div>
                <div className="space-y-2">
                    {scanStream.length > 0 ? scanStream.map((sku, i) => (
                        <div key={i} className="flex items-center justify-between animate-in slide-in-from-top-2">
                            <span className="font-mono text-[10px] text-slate-400">{sku}</span>
                            <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Matched</span>
                        </div>
                    )) : (
                        <p className="text-[10px] text-slate-400 italic py-2">Waiting for first scan...</p>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <button className="flex flex-col items-center justify-center p-4 rounded-3xl border border-slate-100 hover:bg-slate-50 transition-all text-center group">
                    <Camera className="w-5 h-5 text-slate-400 group-hover:text-violet-600 mb-2" />
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Browser Cam</span>
                </button>
                <button className="flex flex-col items-center justify-center p-4 rounded-3xl border border-slate-100 hover:bg-slate-50 transition-all text-center group">
                    <Link className="w-5 h-5 text-slate-400 group-hover:text-violet-600 mb-2" />
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">HID Scanner</span>
                </button>
            </div>
        </div>
      )}

      <div className="mt-8 flex items-center gap-3 p-4 rounded-2xl bg-amber-50 border border-amber-100">
          <AlertCircle className="w-4 h-4 text-amber-600 shrink-0" />
          <p className="text-[9px] text-amber-700 font-medium leading-normal">
              External USB scanners must be in "Keyboard Emulation" mode (HID) to interface directly with the inventory hub.
          </p>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { Search, Eye, CheckCircle, CreditCard } from 'lucide-react';
import { cn } from '@/lib/utils';
import { 
  ArrivalRow, 
  PRIORITY_STYLES, 
  STATUS_STYLES 
} from './DashboardTypes';

interface ArrivalsTableProps {
  arrivals: ArrivalRow[];
  accentColor: string;
}

export function ArrivalsTable({ arrivals, accentColor }: ArrivalsTableProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [checkedIn, setCheckedIn] = useState<Set<string>>(new Set());

  const filteredArrivals = useMemo(() => {
    if (!searchQuery) return arrivals;
    const query = searchQuery.toLowerCase();
    return arrivals.filter((row) =>
      row.patient.toLowerCase().includes(query) ||
      row.token.toLowerCase().includes(query) ||
      row.complaint.toLowerCase().includes(query)
    );
  }, [arrivals, searchQuery]);

  return (
    <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
      <div className="px-6 py-4 border-b border-slate-200 flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-slate-900 font-semibold">Today's Arrivals</h2>
          <span className="text-slate-500 text-sm">{filteredArrivals.length} of {arrivals.length} patients</span>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search patients..."
            className="pl-9 pr-3 py-2 rounded-lg border border-slate-200 text-sm outline-none focus:ring-2 focus:ring-[#2E86AB]/20 w-64"
          />
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-slate-200 bg-slate-50/80">
              {['Token', 'Patient', 'Age/Sex', 'Priority', 'Complaint', 'Wait', 'Status', 'Actions'].map((h) => (
                <th key={h} className="px-4 py-3 text-left text-slate-500 text-xs font-medium uppercase tracking-wide">
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filteredArrivals.length > 0 ? (
              filteredArrivals.map((row) => (
                <tr key={row.token} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 font-mono text-xs font-bold" style={{ color: accentColor }}>{row.token}</td>
                  <td className="px-4 py-3 text-slate-900 font-medium">{row.patient}</td>
                  <td className="px-4 py-3 text-slate-600">{row.ageSex}</td>
                  <td className="px-4 py-3">
                    <span className={cn('px-2 py-0.5 rounded-full text-xs font-medium', PRIORITY_STYLES[row.priority])}>
                      {row.priority}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-slate-600">{row.complaint}</td>
                  <td className="px-4 py-3 text-slate-600">{row.wait}</td>
                  <td className="px-4 py-3">
                    <span className={cn('px-2 py-0.5 rounded-full text-xs font-medium', STATUS_STYLES[row.status])}>
                      {row.status}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-1">
                      <button className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-500 hover:text-slate-900 transition-colors" title="View">
                        <Eye className="w-3.5 h-3.5" />
                      </button>
                      <button
                        onClick={() => setCheckedIn((s) => { const n = new Set(s); n.add(row.token); return n; })}
                        className={cn('p-1.5 rounded-lg transition-colors', checkedIn.has(row.token) ? 'text-emerald-600' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100')}
                        title="Check In"
                      >
                        <CheckCircle className="w-3.5 h-3.5" />
                      </button>
                      <button className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-500 hover:text-slate-900 transition-colors" title="Bill">
                        <CreditCard className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={8} className="px-4 py-8 text-center text-slate-500">
                  No patients match your search.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

