        {isExpiringSoon && (
          <div className="flex items-center gap-2 p-3 bg-rose-50 border border-rose-100 rounded-xl">
            <BadgeAlert className="w-4 h-4 text-rose-500" />
            <p className="text-[10px] font-bold text-rose-600 uppercase tracking-tight">
              License Expiry: {member.licenseExpiry} — Renew immediately
            </p>
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-2 pt-2">
          <button
            onClick={() => onApprove(member.id)}
            className="flex-1 group/btn relative flex items-center justify-center gap-2 py-3 bg-slate-900 overflow-hidden rounded-xl text-white text-xs font-black uppercase tracking-widest transition-all active:scale-95"
          >
            <div className="absolute inset-0 bg-blue-600 translate-y-full group-hover/btn:translate-y-0 transition-transform duration-300" />
            <span className="relative flex items-center gap-2">
              Approve Access
              <CheckCircle2 className="w-3.5 h-3.5" />
            </span>
          </button>
          <button
            onClick={() => onReject(member.id)}
            className="flex items-center justify-center px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-400 hover:text-rose-500 hover:bg-rose-50 hover:border-rose-100 transition-all active:scale-95"
          >
            <XCircle className="w-4 h-4" />
          </button>
          <button className="flex items-center justify-center px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-400 hover:text-blue-600 hover:bg-blue-50 hover:border-blue-100 transition-all active:scale-95">
            <ExternalLink className="w-4 h-4" />
          </button>
        </div>
      </div>
    </motion.div>
  );
}

