'use client';

import { useState, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { ChevronUp, ChevronDown, ChevronLeft, ChevronRight, Download } from 'lucide-react';

export interface Column<T> {
  key: string;
  header: string;
  accessor: (row: T) => React.ReactNode;
  sortable?: boolean;
  width?: string;
}

interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  keyExtractor: (row: T) => string;
  title?: string;
  description?: string;
  searchable?: boolean;
  searchPlaceholder?: string;
  exportable?: boolean;
  exportFilename?: string;
  className?: string;
  emptyState?: React.ReactNode;
  onRowClick?: (row: T) => void;
  rowClassName?: string;
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

/**
 * Data Table Component
 * Provides sorting, pagination, search, and export functionality
 * 
 * Usage:
 * ```tsx
 * <DataTable
 *   data={patients}
 *   columns={[
 *     { key: 'name', header: 'Name', accessor: (p) => p.name, sortable: true },
 *     { key: 'age', header: 'Age', accessor: (p) => p.age, sortable: true },
 *   ]}
 *   keyExtractor={(p) => p.id}
 *   title="Patients"
 *   searchable
 *   exportable
 * />
 * ```
 */
export default function DataTable<T>({
  data,
  columns,
  keyExtractor,
  title,
  description,
  searchable = false,
  searchPlaceholder = 'Search...',
  exportable = false,
  exportFilename = 'export',
  className,
  emptyState,
  onRowClick,
  rowClassName,
}: DataTableProps<T>) {
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Filter data based on search
  const filteredData = useMemo(() => {
    if (!searchQuery) return data;

    const query = searchQuery.toLowerCase();
    return data.filter((row) => {
      return columns.some((col) => {
        const value = String(col.accessor(row)).toLowerCase();
        return value.includes(query);
      });
    });
  }, [data, searchQuery, columns]);

  // Sort data
  const sortedData = useMemo(() => {
    if (!sortConfig) return filteredData;

    const column = columns.find((c) => c.key === sortConfig.key);
    if (!column || !column.sortable) return filteredData;

    return [...filteredData].sort((a, b) => {
      const aValue = String(column.accessor(a));
      const bValue = String(column.accessor(b));

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig, columns]);

  // Paginate data
  const totalPages = Math.ceil(sortedData.length / itemsPerPage);
  const paginatedData = sortedData.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  // Reset page when data changes
  useMemo(() => {
    setCurrentPage(1);
  }, [searchQuery, sortConfig?.key, sortConfig?.direction]);

  const handleSort = (key: string) => {
    const column = columns.find((c) => c.key === key);
    if (!column?.sortable) return;

    setSortConfig((current) => {
      if (!current || current.key !== key) {
        return { key, direction: 'asc' };
      }
      if (current.direction === 'asc') {
        return { key, direction: 'desc' };
      }
      return null;
    });
  };

  const handleExport = () => {
    const headers = columns.map((c) => c.header).join(',');
    const rows = sortedData.map((row) =>
      columns.map((col) => {
        const value = col.accessor(row);
        // Escape values containing commas or quotes
        const str = String(value).replace(/"/g, '""');
        return str.includes(',') ? `"${str}"` : str;
      }).join(',')
    ).join('\n');

    const csv = `${headers}\n${rows}`;
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${exportFilename}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={cn('bg-content-bg rounded-2xl border border-content-border shadow-sm overflow-hidden', className)}>
      {/* Header */}
      {(title || description || searchable || exportable) && (
        <div className="px-6 py-4 border-b border-content-border/60 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            {title && <h3 className="text-lg font-semibold text-ink">{title}</h3>}
            {description && <p className="text-sm text-slate mt-0.5">{description}</p>}
          </div>

          <div className="flex items-center gap-3">
            {searchable && (
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={searchPlaceholder}
                className="px-3 py-2 rounded-lg border border-content-border text-sm focus:outline-none focus:border-mist w-full sm:w-64"
              />
            )}

            {exportable && (
              <button
                onClick={handleExport}
                className="flex items-center gap-2 px-3 py-2 rounded-lg border border-content-border text-sm font-medium text-slate hover:bg-content-border/40 transition-colors"
              >
                <Download className="w-4 h-4" />
                Export
              </button>
            )}
          </div>
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-content-border/40 border-b border-content-border/60">
            <tr>
              {columns.map((column) => (
                <th
                  key={column.key}
                  scope="col"
                  className={cn(
                    'px-6 py-3 text-left text-xs font-semibold text-slate uppercase tracking-wider',
                    column.sortable && 'cursor-pointer hover:text-charcoal select-none',
                    onRowClick && 'cursor-pointer'
                  )}
                  style={{ width: column.width }}
                  onClick={() => column.sortable && handleSort(column.key)}
                >
                  <div className="flex items-center gap-1">
                    {column.header}
                    {column.sortable && (
                      <span className="flex flex-col">
                        <ChevronUp 
                          className={cn(
                            'w-3 h-3 -mb-1',
                            sortConfig?.key === column.key && sortConfig.direction === 'asc'
                              ? 'text-ink'
                              : 'text-slate/40'
                          )} 
                        />
                        <ChevronDown 
                          className={cn(
                            'w-3 h-3',
                            sortConfig?.key === column.key && sortConfig.direction === 'desc'
                              ? 'text-ink'
                              : 'text-slate/40'
                          )} 
                        />
                      </span>
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>

          <tbody className="divide-y divide-content-border/60">
            {paginatedData.length > 0 ? (
              paginatedData.map((row) => (
                <tr
                  key={keyExtractor(row)}
                  className={cn(
                    'hover:bg-content-border/40 transition-colors',
                    onRowClick && 'cursor-pointer',
                    rowClassName
                  )}
                  onClick={() => onRowClick?.(row)}
                >
                  {columns.map((column) => (
                    <td key={column.key} className="px-6 py-4 whitespace-nowrap text-sm text-ink">
                      {column.accessor(row)}
                    </td>
                  ))}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={columns.length} className="px-6 py-12 text-center">
                  {emptyState || (
                    <div className="text-slate/70">
                      <p className="text-sm">No data available</p>
                    </div>
                  )}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="px-6 py-4 border-t border-content-border/60 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate">
              Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, sortedData.length)} of {sortedData.length}
            </span>

            <select
              value={itemsPerPage}
              onChange={(e) => setItemsPerPage(Number(e.target.value))}
              className="ml-2 px-2 py-1 rounded border border-content-border text-sm"
            >
              {[10, 25, 50, 100].map((n) => (
                <option key={n} value={n}>{n} per page</option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-1">
            <button
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="p-1 rounded-lg text-slate hover:bg-content-border/60 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>

            <div className="flex items-center gap-1">
              {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                <button
                  key={page}
                  onClick={() => setCurrentPage(page)}
                  className={cn(
                    'w-8 h-8 rounded-lg text-sm font-medium transition-colors',
                    currentPage === page
                      ? 'bg-ink text-content-bg'
                      : 'text-slate hover:bg-content-border/60'
                  )}
                >
                  {page}
                </button>
              ))}
            </div>

            <button
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="p-1 rounded-lg text-slate hover:bg-content-border/60 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export { DataTable };

