import logger from '@/lib/logger';

/* ──────────────────────────────────────── types */
export type ScribeStatus = 'idle' | 'connecting' | 'recording' | 'processing' | 'error' | 'closed' | 'reconnecting';

export interface TranscriptSegment {
    id: string;
    speaker: 'doctor' | 'patient';
