    // WebSocket message handler
    const handleMessage = useCallback((event: MessageEvent) => {
        try {
            const data = JSON.parse(event.data);

            switch (data.type) {
                case 'transcript_segment':
                    const segment: TranscriptSegment = {
                        id: data.id || crypto.randomUUID(),
                        speaker: data.speaker,
                        text: data.text,
                        timestamp: data.timestamp || new Date().toISOString(),
                        confidence: data.confidence || 0.95,
                    };
                    setTranscript(prev => [...prev, segment]);
                    onSegment?.(segment);
                    break;

                case 'soap_generated':
                    const soapNote: SOAPNote = {
                        subjective: data.subjective,
                        objective: data.objective,
                        assessment: data.assessment,
                        plan: data.plan,
                        generatedAt: data.generatedAt || new Date().toISOString(),
                        aiModel: data.aiModel || 'AfyaAI Scribe',
                        confidenceScore: data.confidenceScore || 0.9,
                    };
                    setSOAP(soapNote);
                    onSOAPGenerated?.(soapNote);
                    setIsGeneratingSOAP(false);
                    setStatus('idle');
                    break;

                case 'status_update':
                    setStatus(data.status);
                    break;

                case 'error':
                    logger.error('WebSocket error', { message: data.message });
                    setStatus('error');
                    break;
            }
        } catch (error) {
            logger.error('Error parsing WebSocket message', { error });
        }
    }, [onSegment, onSOAPGenerated]);

    // WebSocket error handler
    const handleError = useCallback((error: Event) => {
        logger.error('WebSocket connection error', { error });
        setStatus('error');

        // Attempt reconnection with exponential backoff
        if (retryCountRef.current < maxRetries) {
            retryCountRef.current++;
            setStatus('reconnecting');
            reconnectTimeoutRef.current = setTimeout(() => {
                connectWebSocket();
            }, Math.min(1000 * 2 ** retryCountRef.current, 10000));
        } else {
            setStatus('error');
        }
    }, []);

    // WebSocket close handler
    const handleClose = useCallback((event: CloseEvent) => {
        setIsConnected(false);
        setStatus('closed');

        // Clear heartbeat interval
        if (heartbeatIntervalRef.current) {
            clearInterval(heartbeatIntervalRef.current);
            heartbeatIntervalRef.current = null;
        }

        // Attempt reconnection if not closed intentionally
        if (!event.wasClean && retryCountRef.current < maxRetries) {
            retryCountRef.current++;
            setStatus('reconnecting');
            reconnectTimeoutRef.current = setTimeout(() => {
                connectWebSocket();
            }, Math.min(1000 * 2 ** retryCountRef.current, 10000));
        }
    }, []);

    // Connect to WebSocket
    const connectWebSocket = useCallback(() => {
        if (!shouldUseWebSocket) return;

        try {
            const wsUrl = `wss://api.afyahero.co.ke/v1/ai/scribe/ws?consultation_id=${consultationId}`;
            wsRef.current = new WebSocket(wsUrl);

            wsRef.current.onopen = () => {
                setIsConnected(true);
                setStatus('idle');
                retryCountRef.current = 0;

                // Send heartbeat every 30 seconds to keep connection alive
                heartbeatIntervalRef.current = setInterval(() => {
                    if (wsRef.current?.readyState === WebSocket.OPEN) {
                        wsRef.current.send(JSON.stringify({ type: 'heartbeat' }));
                    }
                }, 30000);
            };

            wsRef.current.onmessage = handleMessage;
            wsRef.current.onerror = handleError;
            wsRef.current.onclose = handleClose;
        } catch (error) {
            logger.error('Failed to connect to WebSocket', { error });
            setStatus('error');
        }
    }, [consultationId, shouldUseWebSocket, handleMessage, handleError, handleClose]);

    // Simulate streaming transcript segments in dev
    const simulateSegments = useCallback(() => {
        const idx = segmentIndexRef.current;
        if (idx >= DEMO_SEGMENTS.length) return;

        const raw = DEMO_SEGMENTS[idx];
        const seg: TranscriptSegment = {
            id: crypto.randomUUID(),
            timestamp: new Date().toISOString(),
            ...raw,
        };
        segmentIndexRef.current = idx + 1;

        setTranscript((prev) => [...prev, seg]);
        onSegment?.(seg);

        // Auto-drafting check
        segmentCountRef.current += 1;
        if (segmentCountRef.current % autoDraftInterval === 0) {
            // Auto draft deferred to explicit action to avoid re-entrancy during simulation stream.
        }

        const next = DEMO_SEGMENTS[idx + 1];
        if (next) {
            const delay = 2000 + Math.random() * 2000;
            simulationTimerRef.current = setTimeout(simulateSegments, delay);
        }
    }, [onSegment, autoDraftInterval]);

    const startRecording = useCallback(() => {
        if (status === 'recording') return;

        if (shouldUseWebSocket) {
            setStatus('connecting');
            if (wsRef.current?.readyState === WebSocket.OPEN) {
                wsRef.current.send(JSON.stringify({ type: 'start_recording' }));
                setStatus('recording');
            } else {
                connectWebSocket();
            }
        } else {
            // Development simulation mode
            setStatus('connecting');
            setTimeout(() => {
                setStatus('recording');
                segmentIndexRef.current = 0;
                simulationTimerRef.current = setTimeout(simulateSegments, 800);
            }, 600);
        }
    }, [status, shouldUseWebSocket, connectWebSocket, simulateSegments]);

    const stopRecording = useCallback(() => {
        if (shouldUseWebSocket) {
            if (wsRef.current?.readyState === WebSocket.OPEN) {
                wsRef.current.send(JSON.stringify({ type: 'stop_recording' }));
            }
        } else {
            // Development simulation mode
            if (simulationTimerRef.current) {
                clearTimeout(simulationTimerRef.current);
                simulationTimerRef.current = null;
            }
        }
        setStatus('idle');
    }, [shouldUseWebSocket]);

    const generateSOAP = useCallback(() => {
        if (isGeneratingSOAP) return;
        setIsGeneratingSOAP(true);
        setStatus('processing');

        if (shouldUseWebSocket) {
            if (wsRef.current?.readyState === WebSocket.OPEN) {
                wsRef.current.send(JSON.stringify({ 
                    type: 'generate_soap', 
                    transcript: transcript 
                }));
            }
        } else {
            // Development simulation mode
            setTimeout(() => {
                setSOAP(DEMO_SOAP);
                onSOAPGenerated?.(DEMO_SOAP);
                setIsGeneratingSOAP(false);
                setStatus('idle');
            }, 2800);
        }
    }, [isGeneratingSOAP, transcript, shouldUseWebSocket, onSOAPGenerated]);

    const clearTranscript = useCallback(() => {
        setTranscript([]);
        setSOAP(null);
        segmentIndexRef.current = 0;

        if (shouldUseWebSocket) {
            if (wsRef.current?.readyState === WebSocket.OPEN) {
                wsRef.current.send(JSON.stringify({ type: 'clear_transcript' }));
            }
        }
    }, [shouldUseWebSocket]);

    const reconnect = useCallback(() => {
        if (shouldUseWebSocket) {
            retryCountRef.current = 0;
            connectWebSocket();
        }
    }, [shouldUseWebSocket, connectWebSocket]);

    // Initialize WebSocket connection
    useEffect(() => {
        if (shouldUseWebSocket) {
            connectWebSocket();
        }

        return () => {
            // Cleanup on unmount
            if (wsRef.current) {
                wsRef.current.close();
            }
            if (simulationTimerRef.current) {
                clearTimeout(simulationTimerRef.current);
            }
            if (heartbeatIntervalRef.current) {
                clearInterval(heartbeatIntervalRef.current);
            }
            if (reconnectTimeoutRef.current) {
                clearTimeout(reconnectTimeoutRef.current);
            }
        };
    }, [shouldUseWebSocket, connectWebSocket]);

    return {
        status,
        transcript,
        soap,
        isGeneratingSOAP,
        isConnected,
        startRecording,
        stopRecording,
        generateSOAP,
        clearTranscript,
        reconnect,
    };
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { HealthNewsArticle, fetchHealthNews } from '@/lib/health-news-service';

export function useHealthNews() {
  const [articles, setArticles] = useState<HealthNewsArticle[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastFetched, setLastFetched] = useState<Date | null>(null);

  const loadNews = useCallback(async () => {
    setLoading(true);
    setError(null);

    const result = await fetchHealthNews();

    if (result.success) {
      setArticles(result.articles);
      setLastFetched(new Date());
    } else {
      setError(result.error || 'Failed to load news');
    }

    setLoading(false);
  }, []);

  useEffect(() => {
    loadNews();

    // Auto refresh every 15 minutes
    const interval = setInterval(() => {
      loadNews();
    }, 15 * 60 * 1000);

    return () => clearInterval(interval);
  }, [loadNews]);

  return {
    articles,
    loading,
    error,
    lastFetched,
    refresh: loadNews
  };
}

