/**
 * React Hook for Resilient Mesh Networking
 *
 * Integrates mesh networking into React components with real-time status updates
 * and automatic lifecycle management.
 */

'use client';

import { useEffect, useState, useCallback, useRef } from 'react';
import { MeshNetworkManager, MeshMessage, MeshNode, MessagePriority } from '../lib/mesh-network';

let globalMeshManager: MeshNetworkManager | null = null;

/**
 * Get or create global mesh network instance
 */
function getGlobalMeshManager(): MeshNetworkManager {
  if (!globalMeshManager) {
    const nodeId = `node-${Math.random().toString(36).substring(2, 10)}`;
    globalMeshManager = new MeshNetworkManager(nodeId);
  }
  return globalMeshManager;
}

/**
 * React hook for mesh network functionality
 */
export function useMeshNetwork() {
  const meshManager = useRef(getGlobalMeshManager());
  const [status, setStatus] = useState(meshManager.current.getMeshStatus());
  const [peers, setPeers] = useState<MeshNode[]>([]);
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    const manager = meshManager.current;

    // Start mesh network when component mounts
    manager.start();
    setIsInitialized(true);

    // Status update interval
    const statusInterval = setInterval(() => {
      setStatus(manager.getMeshStatus());
      setPeers(Array.from(manager.peers.values()));
    }, 2000);

    // Listen for incoming messages
    const handleMeshMessage = (event: Event) => {
      const customEvent = event as CustomEvent<MeshMessage>;
      // Dispatch to application event system
      window.dispatchEvent(new CustomEvent('mesh:received', { detail: customEvent.detail }));
    };

    window.addEventListener('mesh:message', handleMeshMessage);

    return () => {
      clearInterval(statusInterval);
      window.removeEventListener('mesh:message', handleMeshMessage);
      manager.saveState();
    };
  }, []);

  const sendMessage = useCallback((destination: string, payload: unknown, priority: MessagePriority = 'normal') => {
    const message: MeshMessage = {
      id: `${Date.now()}-${Math.random().toString(36)}`,
      type: 'data',
      source: meshManager.current.nodeId,
      destination,
      payload,
      priority,
      timestamp: Date.now(),
      ttl: 3600,
      hopCount: 0,
      previousHop: '',
      signature: '',
    };

    return meshManager.current.routeMessage(message);
  }, []);

  const broadcastMessage = useCallback((payload: unknown, priority: MessagePriority = 'normal') => {
    meshManager.current.broadcast({
      type: 'data',
      destination: '*',
      payload,
      priority,
      ttl: 3600,
      signature: '',
    });
  }, []);

  return {
    nodeId: meshManager.current.nodeId,
    status,
    peers,
    isInitialized,
    sendMessage,
    broadcastMessage,
    getMeshStatus: () => meshManager.current.getMeshStatus(),
  };
}

/**
 * useRealtimeBeds
 *
 * Subscribes to real-time updates on the hospital_beds table via Supabase
 * Realtime. Returns the full bed grid grouped by ward.
 *
 * IMPORTANT: always call supabase.removeChannel(channel) in cleanup to prevent
 * memory leaks (see AfyaHero fullstack rules).
 */

'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import type { RealtimeChannel } from '@supabase/supabase-js';
import logger from '@/lib/logger';

/* ──────────────────────────────────────── types */
export type BedStatus = 'available' | 'occupied' | 'reserved' | 'maintenance' | 'cleaning';

export interface Bed {
    id: string;
    bed_number: string;
    ward_id: string;
    ward_name: string;
    status: BedStatus;
    patient_id?: string;
    patient_name?: string;
    admitted_at?: string;
    expected_discharge?: string;
    hospital_id: string;
    notes?: string;
}

export type BedsByWard = Record<string, Bed[]>;

export type BedConnectionStatus = 'connecting' | 'connected' | 'error' | 'closed';

interface UseRealtimeBedsReturn {
    beds: Bed[];
    bedsByWard: BedsByWard;
    connectionStatus: BedConnectionStatus;
    stats: {
        total: number;
        available: number;
        occupied: number;
        reserved: number;
        maintenance: number;
        occupancyRate: number;
    };
    refresh: () => Promise<void>;
}

/* ──────────────────────────────────────── helpers */
function groupByWard(beds: Bed[]): BedsByWard {
    return beds.reduce<BedsByWard>((acc, bed) => {
        if (!acc[bed.ward_name]) acc[bed.ward_name] = [];
        acc[bed.ward_name].push(bed);
        return acc;
    }, {});
}

function computeStats(beds: Bed[]) {
    const total       = beds.length;
    const available   = beds.filter(b => b.status === 'available').length;
    const occupied    = beds.filter(b => b.status === 'occupied').length;
    const reserved    = beds.filter(b => b.status === 'reserved').length;
    const maintenance = beds.filter(b => b.status === 'maintenance' || b.status === 'cleaning').length;
    const occupancyRate = total > 0 ? Math.round((occupied / total) * 100) : 0;
    return { total, available, occupied, reserved, maintenance, occupancyRate };
}

/* ──────────────────────────────────────── hook */
export function useRealtimeBeds(hospitalId: string, wardId?: string): UseRealtimeBedsReturn {
    const [beds, setBeds] = useState<Bed[]>([]);
    const [connectionStatus, setConnectionStatus] = useState<BedConnectionStatus>('connecting');
    const channelRef = useRef<RealtimeChannel | null>(null);
    const mountedRef = useRef(true);

    const fetchBeds = useCallback(async () => {
        if (!hospitalId) return;
        let query = supabase
            .from('hospital_beds')
            .select('*')
            .eq('hospital_id', hospitalId)
            .order('ward_name', { ascending: true })
            .order('bed_number', { ascending: true });

        if (wardId) query = query.eq('ward_id', wardId);

        const { data, error } = await query;
        if (error) {
            logger.error('[useRealtimeBeds] fetch error', { error: error.message, hospitalId, wardId });
            return;
        }
        if (mountedRef.current) {
            setBeds((data ?? []) as Bed[]);
        }
    }, [hospitalId, wardId]);

    useEffect(() => {
        mountedRef.current = true;
        void fetchBeds();

        const channelName = wardId
            ? `beds:hospital_id=eq.${hospitalId}:ward_id=eq.${wardId}`
            : `beds:hospital_id=eq.${hospitalId}`;

        const filter = wardId
            ? `hospital_id=eq.${hospitalId}`
            : `hospital_id=eq.${hospitalId}`;

        const channel = supabase
            .channel(channelName)
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'hospital_beds', filter },
                (payload) => {
                    if (!mountedRef.current) return;
                    setBeds((prev) => {
                        if (payload.eventType === 'INSERT') {
                            return [...prev, payload.new as Bed];
                        }
                        if (payload.eventType === 'UPDATE') {
                            return prev.map((b) =>
                                b.id === payload.new.id ? (payload.new as Bed) : b
                            );
                        }
                        if (payload.eventType === 'DELETE') {
                            return prev.filter((b) => b.id !== payload.old.id);
                        }
                        return prev;
                    });
                }
            )
            .subscribe((status) => {
                if (!mountedRef.current) return;
                if (status === 'SUBSCRIBED') setConnectionStatus('connected');
                else if (status === 'CHANNEL_ERROR') setConnectionStatus('error');
                else if (status === 'CLOSED') setConnectionStatus('closed');
            });

        channelRef.current = channel;

        return () => {
            mountedRef.current = false;
            /* critical: always remove channel on unmount */
            if (channelRef.current) {
                void supabase.removeChannel(channelRef.current);
                channelRef.current = null;
            }
        };
    }, [hospitalId, wardId, fetchBeds]);

    return {
        beds,
        bedsByWard: groupByWard(beds),
        connectionStatus,
        stats: computeStats(beds),
        refresh: fetchBeds,
    };
}

