'use client';

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import { DEFAULT_AI_CONSENT_MODE, normalizeAIConsentMode, type AIConsentMode } from '@/lib/ai-policy';

interface AIConsentContextValue {
  consentMode: AIConsentMode;
  setConsentMode: (mode: AIConsentMode) => void;
  isConsentPending: boolean;
  allowsExternalAI: boolean;
}

const STORAGE_KEY = 'ai-consent-mode';

const AIConsentContext = createContext<AIConsentContextValue | undefined>(undefined);

export function AIConsentProvider({ children }: { children: ReactNode }) {
  const [consentMode, setConsentModeState] = useState<AIConsentMode>(DEFAULT_AI_CONSENT_MODE);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const storedValue = window.localStorage.getItem(STORAGE_KEY);
    setConsentModeState(normalizeAIConsentMode(storedValue));
  }, []);

  const setConsentMode = (mode: AIConsentMode) => {
    setConsentModeState(mode);

    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, mode);
    }
  };

  const value = useMemo(
    () => ({
      consentMode,
      setConsentMode,
      isConsentPending: consentMode === 'pending',
      allowsExternalAI: consentMode === 'external_anonymized',
    }),
    [consentMode]
  );

  return <AIConsentContext.Provider value={value}>{children}</AIConsentContext.Provider>;
}

export function useAIConsent(): AIConsentContextValue {
  const context = useContext(AIConsentContext);

  if (!context) {
    throw new Error('useAIConsent must be used within an AIConsentProvider');
  }

  return context;
}

/**
 * Authentication Middleware for AfyaHero Health API Routes
 * 
 * Provides comprehensive authentication and authorization:
 * - Session validation for API routes
 * - CSRF protection
 * - Rate limiting per role
 * - Request authentication wrapper
 * - Hospital-scoped access control
 */

import { NextRequest, NextResponse } from 'next/server';
import type { PortalRole } from '@/types';
import { getSession } from '@/lib/auth';
import { canPerformAction, type AccessCheckResult } from '@/lib/rbac';
import {
  detectXSS,
  detectSQLInjection,
  sanitizeObject,
} from '@/lib/input-validation';
import logger from '@/lib/logger';

// ─── Types ────────────────────────────────────────────────────────────────────

export interface AuthenticatedRequest extends NextRequest {
  userId?: string;
  userRole?: PortalRole;
  hospitalId?: string;
  requestId?: string;
}

export interface AuthMiddlewareOptions {
  /** Required role for access */
  requiredRole?: PortalRole | PortalRole[];
  /** Required permission (category:action) */
  requiredPermission?: { category: string; action: string };
  /** Allow access if user has any of these roles */
  anyRole?: PortalRole[];
  /** Skip authentication for this route */
  public?: boolean;
  /** Require hospital ID match */
  requireHospitalMatch?: boolean;
}

export interface AuthResponse {
  authenticated: boolean;
  session?: {
    id: string;
    email: string;
    role: PortalRole;
    hospitalId: string;
    name: string;
  };
  error?: {
    code: string;
    message: string;
    status: number;
  };
}

// ─── Rate Limiting Configuration ──────────────────────────────────────────────

const RATE_LIMITS = {
  // Requests per minute by role
  reception: 120,
  medical: 200,
  lab: 150,
  pharmacy: 150,
  admin: 300,
  super_admin: 500,
  default: 60,
};

// ─── Session Validation ───────────────────────────────────────────────────────

/**
 * Validate a user session from the request
 */
export async function validateSession(_request: NextRequest): Promise<AuthResponse> {
  try {
    const session = await getSession();
    
    if (!session) {
      return {
        authenticated: false,
        error: {
          code: 'UNAUTHORIZED',
          message: 'No valid session found',
          status: 401,
        },
      };
    }
    
    // Check if session is expired
    const now = Date.now();
    const sessionAge = now - session.issuedAt;
    const maxSessionAge = 24 * 60 * 60 * 1000; // 24 hours
    
    if (sessionAge > maxSessionAge) {
      return {
        authenticated: false,
        error: {
          code: 'SESSION_EXPIRED',
          message: 'Session has expired',
          status: 401,
        },
      };
    }
    
    // Check inactivity timeout
    const inactivityTimeout = parseInt(process.env.SESSION_INACTIVITY_TIMEOUT_MINUTES || '20') * 60 * 1000;
    const timeSinceLastActivity = now - session.lastActivityAt;
    
    if (timeSinceLastActivity > inactivityTimeout) {
      return {
        authenticated: false,
        error: {
          code: 'SESSION_INACTIVE',
          message: 'Session has timed out due to inactivity',
          status: 401,
        },
      };
    }
    
    return {
      authenticated: true,
      session: {
        id: session.id,
        email: session.email,
        role: session.role,
        hospitalId: session.hospitalId,
        name: session.name,
      },
    };
  } catch (error) {
    logger.error('Session validation failed', { error: error instanceof Error ? error.message : String(error) });
    return {
      authenticated: false,
      error: {
        code: 'SESSION_ERROR',
        message: 'Failed to validate session',
        status: 500,
      },
    };
  }
}

// ─── Role Validation ──────────────────────────────────────────────────────────

/**
 * Check if a role matches the required role(s)
 */
export function validateRole(
  userRole: PortalRole,
  options: AuthMiddlewareOptions
): { valid: boolean; error?: string } {
  // Check specific required role
  if (options.requiredRole) {
    if (Array.isArray(options.requiredRole)) {
      if (!options.requiredRole.includes(userRole)) {
        return {
          valid: false,
          error: `Required role: ${options.requiredRole.join(' or ')}`,
        };
      }
    } else if (userRole !== options.requiredRole) {
      return {
        valid: false,
        error: `Required role: ${options.requiredRole}`,
      };
    }
  }
  
  // Check anyRole (OR condition)
  if (options.anyRole && options.anyRole.length > 0) {
    if (!options.anyRole.includes(userRole)) {
      return {
        valid: false,
        error: `Required roles: ${options.anyRole.join(' or ')}`,
      };
    }
  }
  
  return { valid: true };
}

// ─── Permission Validation ────────────────────────────────────────────────────

/**
 * Validate that a user has the required permission
 */
export function validatePermission(
  userRole: PortalRole,
  userHospitalId: string | null,
  targetHospitalId: string,
  permission: { category: string; action: string },
  isOwnResource: boolean = false
): AccessCheckResult {
  return canPerformAction({
    userRole,
    userHospitalId,
    targetHospitalId,
    resourceType: permission.category,
    action: permission.action as 'create' | 'read' | 'update' | 'delete',
    isOwnResource,
  });
}

// ─── CSRF Protection ──────────────────────────────────────────────────────────

/**
 * Validate CSRF token from request
 */
export function validateCSRFToken(request: NextRequest): { valid: boolean; error?: string } {
  // Skip CSRF validation for GET requests
  if (request.method === 'GET' || request.method === 'HEAD' || request.method === 'OPTIONS') {
    return { valid: true };
  }
  
  const csrfToken = request.headers.get('X-CSRF-Token');
  const cookieToken = request.cookies.get('csrf_token')?.value;
  
  if (!csrfToken && !cookieToken) {
    // If no CSRF tokens are set, we might be using a different protection mechanism
    // or this is a new session. Allow but log.
    logger.warn('No CSRF token found in request');
    return { valid: true };
  }
  
  if (csrfToken && cookieToken && csrfToken !== cookieToken) {
    return {
      valid: false,
      error: 'CSRF token mismatch',
    };
  }
  
  // Check origin header for cross-site requests
  const origin = request.headers.get('Origin');
  const host = request.headers.get('Host');
  
  if (origin && host) {
    const originUrl = new URL(origin);
    if (originUrl.hostname !== host) {
      return {
        valid: false,
        error: 'Cross-origin request blocked',
      };
    }
  }
  
  return { valid: true };
}

// ─── Input Security Validation ────────────────────────────────────────────────

/**
 * Validate request input for security threats
 */
export function validateInputSecurity(body: unknown): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  
  if (typeof body !== 'object' || body === null) {
    return { valid: true, errors: [] };
  }
  
  // Check for XSS in string fields
  const checkForXSS = (obj: unknown, path: string = ''): void => {
    if (typeof obj === 'string') {
      if (detectXSS(obj)) {
        errors.push(`XSS detected in field: ${path || 'body'}`);
      }
      if (detectSQLInjection(obj)) {
        errors.push(`SQL injection pattern detected in field: ${path || 'body'}`);
      }
    } else if (typeof obj === 'object' && obj !== null) {
      for (const [key, value] of Object.entries(obj)) {
        checkForXSS(value, path ? `${path}.${key}` : key);
      }
    }
  };
  
  checkForXSS(body);
  
  return {
    valid: errors.length === 0,
    errors,
  };
}

// ─── Rate Limiting ────────────────────────────────────────────────────────────

/**
 * Get rate limit for a role
 */
export function getRateLimitForRole(role: PortalRole): number {
  return RATE_LIMITS[role] || RATE_LIMITS.default;
}

/**
 * Check rate limit using Upstash Redis
 */
export async function checkRateLimit(
  userId: string,
  role: PortalRole
): Promise<{ allowed: boolean; remaining: number; reset: number }> {
  try {
    const limit = getRateLimitForRole(role);
    
    // Check if Upstash is configured
    if (!process.env.UPSTASH_REDIS_REST_URL || !process.env.UPSTASH_REDIS_REST_TOKEN) {
      // No rate limiting without Redis
      return { allowed: true, remaining: limit, reset: Date.now() + 60000 };
    }
    
    const { Redis } = await import('@upstash/redis');
    const redis = new Redis({
      url: process.env.UPSTASH_REDIS_REST_URL,
      token: process.env.UPSTASH_REDIS_REST_TOKEN,
    });
    
    const key = `rate_limit:${userId}:${Math.floor(Date.now() / 60000)}`;
    const current = await redis.get(key);
    const count = Number(current || 0) + 1;
    
    if (count === 1) {
      await redis.setex(key, 60, 1);
    } else {
      await redis.setex(key, 60, count);
    }
    
    const remaining = Math.max(0, limit - count);
    const reset = Math.ceil(Date.now() / 60000) * 60000;
    
    return {
      allowed: count <= limit,
      remaining,
      reset,
    };
  } catch (error) {
    // If rate limiting fails, allow the request but log the error
    logger.error('Rate limit check failed', { error: error instanceof Error ? error.message : String(error) });
    return { allowed: true, remaining: 0, reset: Date.now() + 60000 };
  }
}

// ─── Main Middleware Function ─────────────────────────────────────────────────

/**
 * Main authentication middleware for API routes
 * 
 * Usage:
 * ```typescript
 * export async function GET(request: NextRequest) {
 *   const authResult = await withAuth(request, { requiredRole: 'medical' });
 *   if (!authResult.authenticated) {
 *     return authResult.response;
 *   }
 *   // Proceed with authenticated request
 * }
 * ```
 */
export async function withAuth(
  request: NextRequest,
  options: AuthMiddlewareOptions = {}
): Promise<{ authenticated: boolean; response?: NextResponse; session?: AuthResponse['session'] }> {
  const requestId = request.headers.get('X-Request-ID') || crypto.randomUUID();
  
  // Skip authentication for public routes
  if (options.public) {
    // Still validate input security for public routes
    if (request.method !== 'GET' && request.method !== 'HEAD' && request.method !== 'OPTIONS') {
      const body = await request.clone().json().catch(() => null);
      if (body) {
        const securityCheck = validateInputSecurity(body);
        if (!securityCheck.valid) {
          return {
            authenticated: false,
            response: NextResponse.json(
              { error: 'Invalid input', details: securityCheck.errors },
              { status: 400 }
            ),
          };
        }
      }
    }
    return { authenticated: true };
  }
  
  // Validate session
  const sessionResult = await validateSession(request);
  if (!sessionResult.authenticated) {
    logger.warn('Authentication failed', {
      requestId,
      path: request.nextUrl.pathname,
      error: sessionResult.error?.code,
    });
    
    return {
      authenticated: false,
      response: NextResponse.json(
        { error: sessionResult.error?.message, code: sessionResult.error?.code },
        { status: sessionResult.error?.status || 401 }
      ),
    };
  }
  
  const session = sessionResult.session!;
  
  // Validate CSRF token
  const csrfResult = validateCSRFToken(request);
  if (!csrfResult.valid) {
    logger.warn('CSRF validation failed', {
      requestId,
      userId: session.id,
      path: request.nextUrl.pathname,
    });
    
    return {
      authenticated: false,
      response: NextResponse.json(
        { error: csrfResult.error, code: 'CSRF_INVALID' },
        { status: 403 }
      ),
    };
  }
  
  // Validate role
  if (options.requiredRole || options.anyRole) {
    const roleResult = validateRole(session.role, options);
    if (!roleResult.valid) {
      logger.warn('Role validation failed', {
        requestId,
        userId: session.id,
        userRole: session.role,
        path: request.nextUrl.pathname,
        error: roleResult.error,
      });
      
      return {
        authenticated: false,
        response: NextResponse.json(
          { error: 'Insufficient permissions', details: roleResult.error, code: 'ROLE_INVALID' },
          { status: 403 }
        ),
      };
    }
  }
  
  // Validate permission
  if (options.requiredPermission) {
    const permissionResult = validatePermission(
      session.role,
      session.hospitalId,
      session.hospitalId, // Target hospital is user's hospital
      options.requiredPermission
    );
    
    if (!permissionResult.allowed) {
      logger.warn('Permission validation failed', {
        requestId,
        userId: session.id,
        userRole: session.role,
        path: request.nextUrl.pathname,
        error: permissionResult.reason,
      });
      
      return {
        authenticated: false,
        response: NextResponse.json(
          { error: permissionResult.reason, code: 'PERMISSION_DENIED' },
          { status: 403 }
        ),
      };
    }
  }
  
  // Check rate limit
  const rateLimitResult = await checkRateLimit(session.id, session.role);
  if (!rateLimitResult.allowed) {
    logger.warn('Rate limit exceeded', {
      requestId,
      userId: session.id,
      userRole: session.role,
      path: request.nextUrl.pathname,
    });
    
    return {
      authenticated: false,
      response: NextResponse.json(
        {
          error: 'Rate limit exceeded',
          code: 'RATE_LIMIT_EXCEEDED',
          retryAfter: rateLimitResult.reset,
        },
        {
          status: 429,
          headers: {
            'X-RateLimit-Limit': String(getRateLimitForRole(session.role)),
            'X-RateLimit-Remaining': '0',
            'X-RateLimit-Reset': String(rateLimitResult.reset),
          },
        }
      ),
    };
  }
  
  // Validate input security for non-GET requests
  if (request.method !== 'GET' && request.method !== 'HEAD' && request.method !== 'OPTIONS') {
    const body = await request.clone().json().catch(() => null);
    if (body) {
      const securityCheck = validateInputSecurity(body);
      if (!securityCheck.valid) {
        logger.warn('Input security validation failed', {
          requestId,
          userId: session.id,
          path: request.nextUrl.pathname,
          errors: securityCheck.errors,
        });
        
        return {
          authenticated: false,
          response: NextResponse.json(
            { error: 'Invalid input', details: securityCheck.errors, code: 'INPUT_INVALID' },
            { status: 400 }
          ),
        };
      }
    }
  }
  
  // Log successful authentication
  logger.debug('Authentication successful', {
    requestId,
    userId: session.id,
    userRole: session.role,
    path: request.nextUrl.pathname,
  });
  
  return {
    authenticated: true,
    session,
  };
}

// ─── Hospital-Scoped Data Access ──────────────────────────────────────────────

/**
 * Validate that a user can access data from a specific hospital
 */
export function validateHospitalAccess(
  userHospitalId: string | null,
  targetHospitalId: string
): { allowed: boolean; error?: string } {
  if (!userHospitalId) {
    return {
      allowed: false,
      error: 'User does not belong to any hospital',
    };
  }
  
  if (userHospitalId !== targetHospitalId) {
    return {
      allowed: false,
      error: 'Access denied: Cannot access data from another hospital',
    };
  }
  
  return { allowed: true };
}

// ─── Response Helpers ─────────────────────────────────────────────────────────

/**
 * Add authentication headers to response
 */
export function addAuthHeaders(response: NextResponse, session: AuthResponse['session']): NextResponse {
  if (session) {
    response.headers.set('X-User-Id', session.id);
    response.headers.set('X-User-Role', session.role);
    response.headers.set('X-Hospital-Id', session.hospitalId);
  }
  return response;
}

/**
 * Create an authenticated response with user context
 */
export function createAuthenticatedResponse(
  data: unknown,
  session: AuthResponse['session'],
  options?: { status?: number; headers?: Record<string, string> }
): NextResponse {
  const response = NextResponse.json(data, {
    status: options?.status || 200,
    headers: options?.headers,
  });
  
  return addAuthHeaders(response, session);
}

// ─── Utility Functions ────────────────────────────────────────────────────────

/**
 * Extract hospital ID from request URL or body
 */
export function extractHospitalId(request: NextRequest): string | null {
  // Try to get from URL pathname
  const pathname = request.nextUrl.pathname;
  const hospitalMatch = pathname.match(/\/hospitals\/([a-f0-9-]+)/i);
  if (hospitalMatch) {
    return hospitalMatch[1];
  }
  
  // Try to get from query params
  const hospitalId = request.nextUrl.searchParams.get('hospitalId');
  if (hospitalId) {
    return hospitalId;
  }
  
  return null;
}

/**
 * Sanitize request body
 */
export async function sanitizeRequestBody(request: NextRequest): Promise<unknown> {
  const body = await request.clone().json().catch(() => null);
  if (body) {
    return sanitizeObject(body);
  }
  return null;
}

// ─── Default Exports ──────────────────────────────────────────────────────────

export default {
  withAuth,
  validateSession,
  validateRole,
  validatePermission,
  validateCSRFToken,
  validateInputSecurity,
  checkRateLimit,
  validateHospitalAccess,
  addAuthHeaders,
  createAuthenticatedResponse,
  extractHospitalId,
  sanitizeRequestBody,
  getRateLimitForRole,
};

/**
 * Database Client for AfyaHero Health
 * 
 * Prisma ORM initialization with:
 * - Connection pooling configuration
 * - Transaction support
 * - Error handling
 * - Health checks
 * - Query logging in development
 * 
 * Note: Prisma client must be generated with `npx prisma generate` before use.
 */

// Lazy-load Prisma to avoid build-time errors when client isn't generated
 
let _PrismaClient: any;
 
let _Prisma: any;
 
let _sql: any;

function loadPrisma() {
  if (_PrismaClient) return;
  try {
     
    const prismaModule = require('@prisma/client');
    _PrismaClient = prismaModule.PrismaClient;
    _Prisma = prismaModule.Prisma;
    _sql = prismaModule.sql;
  } catch {
    // Prisma not generated — provide stubs for build
    _PrismaClient = class StubPrismaClient {
       
      async $connect() {}

       
      async $disconnect() {}

       
      async $queryRaw() { return []; }

       
      async $executeRaw() { return 0; }

       
      $use() {}

       
      $extends() { return this; }
    };
    _Prisma = {
      PrismaClientKnownRequestError: class extends Error { code = ''; },
      PrismaClientValidationError: class extends Error {},
      PrismaClientUnknownRequestError: class extends Error {},
      PrismaClientRustPanicError: class extends Error {},
    };
    _sql = () => ({});
  }
}

loadPrisma();

import logger from '@/lib/logger';

let hasLoggedBuildTimeFallback = false;

function shouldAllowBuildTimeStub(): boolean {
  return (
    process.env.NEXT_PHASE === 'phase-production-build' ||
    process.env.npm_lifecycle_event === 'build'
  );
}

function createStubModel() {
  return new Proxy(
    {},
    {
      get: () =>
        async () => {
          return [];
        },
    },
  );
}

function createStubPrismaClientInstance() {
  const base = {
    async $connect() {},
    async $disconnect() {},
    async $queryRaw() { return []; },
    async $executeRaw() { return 0; },
    async $transaction(input: unknown) {
      if (typeof input === 'function') {
        return (input as (tx: unknown) => Promise<unknown>)(createStubPrismaClientInstance());
      }
      return [];
    },
    $use() {},
    $extends() { return this; },
  };

  return new Proxy(base as Record<string, unknown>, {
    get(target, prop: string) {
      if (prop in target) return target[prop];
      return createStubModel();
    },
  });
}

// ─── Types ────────────────────────────────────────────────────────────────────

export interface QueryLog {
  query: string;
  params: unknown[];
  duration: number;
  target: string;
}

// ─── Prisma Client Configuration ──────────────────────────────────────────────

/**
 * Global Prisma client instance
 * Prevents multiple instances in development due to hot reloading
 */
const globalForPrisma = globalThis as unknown as {
   
  prisma: any;
};

/**
 * Create Prisma client with logging configuration
 */
function createPrismaClient() {
  const isDevelopment = process.env.NODE_ENV === 'development';
  try {
    return new _PrismaClient({
      log: isDevelopment
        ? ['query', 'info', 'warn', 'error']
        : ['error'],
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);

    if (!shouldAllowBuildTimeStub()) {
      logger.error('Prisma client initialization failed', {
        error: errorMessage,
      });
      throw error instanceof Error ? error : new Error(errorMessage);
    }

    if (!hasLoggedBuildTimeFallback) {
      hasLoggedBuildTimeFallback = true;
      logger.warn('Falling back to stub Prisma client during build', {
        error: errorMessage,
      });
    }
    return createStubPrismaClientInstance();
  }
}

/**
 * Get or create the Prisma client instance
 */
export function getPrismaClient() {
  if (!globalForPrisma.prisma) {
    globalForPrisma.prisma = createPrismaClient();

    // Set up query logging in development
    if (process.env.NODE_ENV === 'development') {
       
      globalForPrisma.prisma.$use(async (params: any, next: (p: any) => Promise<unknown>) => {
        const before = Date.now();
        const result = await next(params);
        const after = Date.now();

        const duration = after - before;

        // Log slow queries
        if (duration > 100) {
          logger.warn(`Slow query detected: ${params.model}.${params.action} took ${duration}ms`, {
            model: params.model,
            action: params.action,
            duration,
          });
        }

        return result;
      });
    }
  }
  
  return globalForPrisma.prisma;
}

// ─── Singleton Export ─────────────────────────────────────────────────────────

/**
 * Default Prisma client instance
 */
export const prisma = getPrismaClient();

// ─── Multi-Tenancy Support ────────────────────────────────────────────────────

/**
 * Get a Prisma client bound to a specific hospital/facility
 * This enforces tenant isolation at the application level
 */
export function getTenantPrismaClient(hospitalId: string) {
  if (!hospitalId) {
    throw new Error('hospitalId is required for tenant-bound queries');
  }

  return prisma.$extends({
    query: {
      $allModels: {
        async $allOperations({
          model,
          operation,
          args,
          query,
        }: {
          model: string;
          operation: string;
          args: Record<string, unknown>;
          query: (args: Record<string, unknown>) => Promise<unknown>;
        }) {
          // Models that are known to be global or don't have hospitalId
          const globalModels = ['Hospital', 'User', 'UserSession', 'GlobalSettings'];

          if (!globalModels.includes(model)) {
            // Inject hospitalId into the where clause for read/update/delete operations
            if (['findUnique', 'findFirst', 'findMany', 'update', 'updateMany', 'delete', 'deleteMany', 'count', 'aggregate', 'groupBy'].includes(operation)) {
              args.where = { ...(args.where as Record<string, unknown> ?? {}), hospitalId };
            }

            // Inject hospitalId into the data payload for create operations
            if (['create', 'createMany'].includes(operation)) {
              if (Array.isArray(args.data)) {
                args.data = args.data.map((d: Record<string, unknown>) => ({ ...d, hospitalId }));
              } else {
                args.data = { ...(args.data as Record<string, unknown> ?? {}), hospitalId };
              }
            }
          }

          return query(args);
        },
      },
    },
  });
}

// ─── Connection Management ────────────────────────────────────────────────────

/**
 * Connect to the database
 */
export async function connectDatabase(): Promise<void> {
  try {
    await prisma.$connect();
    logger.info('Database connection established');
  } catch (error) {
    logger.error('Failed to connect to database', {
      error: error instanceof Error ? error.message : String(error),
    });
    throw error;
  }
}

/**
 * Disconnect from the database
 */
export async function disconnectDatabase(): Promise<void> {
  try {
    await prisma.$disconnect();
    logger.info('Database connection closed');
  } catch (error) {
    logger.error('Failed to disconnect from database', {
      error: error instanceof Error ? error.message : String(error),
    });
    throw error;
  }
}

/**
 * Check database connection health
 */
export async function checkDatabaseHealth(): Promise<{
  healthy: boolean;
  responseTime?: number;
  error?: string;
}> {
  const startTime = Date.now();
  
  try {
    // Simple query to check connection
    await prisma.$queryRaw`SELECT 1`;
    
    const responseTime = Date.now() - startTime;
    
    return {
      healthy: true,
      responseTime,
    };
  } catch (error) {
    return {
      healthy: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ─── Transaction Support ──────────────────────────────────────────────────────

/**
 * Execute operations within a transaction
 * 
 * @example
 * ```typescript
 * const result = await withTransaction(async (tx) => {
 *   const patient = await tx.patient.create({ data: {...} });
 *   const appointment = await tx.appointment.create({ data: {...} });
 *   return { patient, appointment };
 * });
 * ```
 */
export async function withTransaction<T>(
   
  fn: (tx: any) => Promise<T>,
  options?: {
    timeout?: number;
    maxWait?: number;
  }
): Promise<T> {
  return prisma.$transaction(fn, {
    timeout: options?.timeout ?? 5000,
    maxWait: options?.maxWait ?? 2000,
  });
}

/**
 * Execute multiple operations with retry logic
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  options?: {
    maxRetries?: number;
    delay?: number;
    backoff?: number;
  }
): Promise<T> {
  const {
    maxRetries = 3,
    delay = 100,
    backoff = 2,
  } = options ?? {};
  
  let lastError: Error | undefined;
  
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;
      
      // Don't retry on certain errors
      if (isNonRetryableError(error)) {
        throw error;
      }
      
      if (attempt < maxRetries) {
        const waitTime = delay * Math.pow(backoff, attempt);
        logger.warn(`Database operation failed, retrying in ${waitTime}ms (attempt ${attempt + 1}/${maxRetries})`, {
          error: error instanceof Error ? error.message : String(error),
          attempt: attempt + 1,
          maxRetries,
        });
        
        await sleep(waitTime);
      }
    }
  }
  
  throw lastError;
}

/**
 * Check if an error is non-retryable
 */
function isNonRetryableError(error: unknown): boolean {
  const err = error as Record<string, unknown> | null;
  if (!err || typeof err.code !== 'string') {
    return false;
  }

  // Non-retryable error codes
  const nonRetryableCodes = [
    'P2000', // Value out of range
    'P2001', // Record not found
    'P2002', // Unique constraint failed
    'P2003', // Foreign key constraint failed
    'P2004', // Constraint violation
    'P2005', // Invalid value
    'P2006', // Invalid value for field
    'P2007', // Data validation error
    'P2008', // Query parsing error
    'P2009', // Query validation error
    'P2010', // Raw query failed
    'P2011', // Null constraint violation
    'P2012', // Required value missing
    'P2013', // Required argument missing
    'P2014', // Relation violation
    'P2015', // Related record not found
    'P2016', // JSON error
    'P2017', // Records not connected
    'P2018', // Connected records not found
    'P2019', // Input error
    'P2020', // Value out of range
    'P2021', // Table does not exist
    'P2022', // Column does not exist
    'P2023', // Inconsistent column
    'P2024', // Timeout fetching connection
    'P2025', // Operation relies on missing value
    'P2026', // Unsupported feature
    'P2027', // Multiple database errors
    'P2028', // Transaction already committed
    'P2030', // No full-text index
    'P2031', // MongoDB replica set required
    'P2033', // Number out of range
    'P2034', // Transaction failed due to deadlock
  ];
  
  return nonRetryableCodes.includes(err.code);
}

/**
 * Sleep utility
 */
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// ─── Query Helpers ────────────────────────────────────────────────────────────

/**
 * Execute a raw SQL query using Prisma's parameterized template literals.
 * This is safe against SQL injection because Prisma properly escapes all parameters.
 *
 * @example
 * ```typescript
 * const result = await executeRawQuery<T>(
 *   sql`SELECT * FROM patients WHERE hospital_id = ${hospitalId} AND name LIKE ${'%' + name + '%'}`
 * );
 * ```
 */
export async function executeRawQuery<T = unknown>(
   
  query: any,
): Promise<T[]> {
  try {
     
    const result = await (prisma).$queryRaw(query);
    return result as T[];
  } catch (error) {
    logger.error('Raw query execution failed', {
      error: error instanceof Error ? error.message : String(error),
    });
    throw error;
  }
}

/**
 * Execute a raw SQL command (INSERT, UPDATE, DELETE) using Prisma's parameterized template literals.
 * This is safe against SQL injection because Prisma properly escapes all parameters.
 *
 * @example
 * ```typescript
 * const affected = await executeRawCommand(
 *   sql`UPDATE patients SET status = ${status} WHERE id = ${patientId}`
 * );
 * ```
 */
export async function executeRawCommand(
   
  query: any,
): Promise<number> {
  try {
     
    const result = await (prisma).$executeRaw(query);
    return result;
  } catch (error) {
    logger.error('Raw command execution failed', {
      error: error instanceof Error ? error.message : String(error),
    });
    throw error;
  }
}

// ─── Pagination Helpers ───────────────────────────────────────────────────────

export interface PaginationParams {
  page?: number;
  limit?: number;
  orderBy?: Record<string, 'asc' | 'desc'>;
}

export interface PaginatedResult<T> {
  data: T[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

/**
 * Execute a paginated query
 */
export async function paginate<T>(
  findManyFn: (args: { skip: number; take: number; orderBy?: Record<string, 'asc' | 'desc'> }) => Promise<T[]>,
  countFn: () => Promise<number>,
  params: PaginationParams = {}
): Promise<PaginatedResult<T>> {
  const page = Math.max(1, params.page ?? 1);
  const limit = Math.min(100, Math.max(1, params.limit ?? 20));
  const skip = (page - 1) * limit;
  
  const [data, total] = await Promise.all([
    findManyFn({
      skip,
      take: limit,
      orderBy: params.orderBy,
    }),
    countFn(),
  ]);
  
  const totalPages = Math.ceil(total / limit);
  
  return {
    data,
    total,
    page,
    limit,
    totalPages,
    hasNextPage: page < totalPages,
    hasPrevPage: page > 1,
  };
}

// ─── Error Handling ───────────────────────────────────────────────────────────

/**
 * Handle Prisma-specific errors
 */
export function handlePrismaError(error: unknown): {
  code: string;
  message: string;
  status: number;
} {
  const err = error as Record<string, unknown> | null;
  const code = err?.code as string | undefined;
  const message = err?.message as string | undefined;

  if (code) {
    switch (code) {
      case 'P2002':
        return { code: 'UNIQUE_CONSTRAINT', message: message || 'A record with this unique value already exists', status: 409 };
      case 'P2001':
        return { code: 'NOT_FOUND', message: message || 'Record not found', status: 404 };
      case 'P2025':
        return { code: 'RECORD_NOT_FOUND', message: message || 'Record to operate on was not found', status: 404 };
      case 'P2014':
        return { code: 'RELATION_VIOLATION', message: message || 'Operation would violate relation constraints', status: 400 };
      case 'P2003':
        return { code: 'FOREIGN_KEY_VIOLATION', message: message || 'Operation would violate foreign key constraints', status: 400 };
      case 'P2011':
        return { code: 'NULL_CONSTRAINT', message: message || 'Null value provided for required field', status: 400 };
      case 'P2000':
        return { code: 'VALUE_OUT_OF_RANGE', message: message || 'Value is out of range for the field', status: 400 };
      default:
        return { code: 'DATABASE_ERROR', message: message || 'Database operation failed', status: 500 };
    }
  }

  if (error instanceof Error) {
    return { code: 'VALIDATION_ERROR', message: error.message || 'Data validation failed', status: 400 };
  }

  return {
    code: 'UNKNOWN_ERROR',
    message: error instanceof Error ? error.message : 'An unexpected error occurred',
    status: 500,
  };
}

// ─── Middleware for API Routes ───────────────────────────────────────────────

/**
 * Wrap an API route handler with database connection management
 */
export function withDatabase<T extends (...args: unknown[]) => Promise<Response>>(
  handler: T
): T {
  return (async (...args: unknown[]) => {
    try {
      // Ensure connection
      if (!prisma) {
        await connectDatabase();
      }
      
      return await handler(...args);
    } catch (error) {
      const prismaError = handlePrismaError(error);
      return Response.json(
        { error: prismaError.message, code: prismaError.code },
        { status: prismaError.status }
      );
    }
  }) as T;
}

// ─── Default Export ───────────────────────────────────────────────────────────

export default {
  prisma,
  connectDatabase,
  disconnectDatabase,
  checkDatabaseHealth,
  withTransaction,
  withRetry,
  executeRawQuery,
  executeRawCommand,
  paginate,
  handlePrismaError,
  withDatabase,
};

/**
 * Input Validation Utility for AfyaHero Health
 * 
 * Provides comprehensive input validation and sanitization:
 * - XSS prevention
 * - SQL injection prevention
 * - HTML sanitization
 * - File upload validation
 * - API request validation
 * - Zod schema validation helpers
 */

import { z } from 'zod';

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ValidationResult<T = unknown> {
  success: boolean;
  data?: T;
  errors?: ValidationError[];
  sanitized?: T;
}

export interface ValidationError {
  field: string;
  message: string;
  code: string;
}

export interface SanitizationOptions {
  allowHtml?: boolean;
  maxLength?: number;
  allowedTags?: string[];
}

// ─── Dangerous Patterns ───────────────────────────────────────────────────────

/**
 * Patterns that indicate potential XSS attacks
 */
const XSS_PATTERNS = [
  /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
  /javascript\s*:/gi,
  /on\w+\s*=/gi,
  /<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi,
  /<object\b[^<]*(?:(?!<\/object>)<[^<]*)*<\/object>/gi,
  /<embed\b[^<]*(?:(?!<\/embed>)<[^<]*)*<\/embed>/gi,
  /expression\s*\(/gi,
  /vbscript\s*:/gi,
  /data\s*:[^,]*;base64/gi,
];

/**
 * Patterns that indicate potential SQL injection
 */
const SQL_INJECTION_PATTERNS = [
  /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|EXEC|EXECUTE)\b)/gi,
  /(--|;|\/\*|\*\/)/g,
  /(\b(UNION|JOIN|WHERE|FROM|INTO|VALUES|SET)\b)/gi,
  /(\b(OR|AND)\b\s+\d+\s*=\s*\d+)/gi,
  /(\b(OR|AND)\b\s+['"]?\w+['"]?\s*=\s*['"]?\w+['"]?)/gi,
  /(['"])\s*(OR|AND)\s*\1/gi,
];

/**
 * Sensitive fields that should never be logged or exposed
 */
const SENSITIVE_FIELDS = [
  'password',
  'token',
  'apiKey',
  'api_key',
  'secret',
  'authorization',
  'cookie',
  'session',
  'creditCard',
  'credit_card',
  'ssn',
  'nationalId',
  'national_id',
  'cvv',
];

// ─── XSS Prevention ───────────────────────────────────────────────────────────

/**
 * Detect potential XSS attacks in a string
 */
export function detectXSS(input: string): boolean {
  if (typeof input !== 'string') return false;
  
  return XSS_PATTERNS.some(pattern => pattern.test(input));
}

/**
 * Sanitize a string by removing potential XSS content
 */
export function sanitizeXSS(input: string, options: SanitizationOptions = {}): string {
  if (typeof input !== 'string') return String(input);
  
  let sanitized = input;
  
  // Remove script tags and their content
  sanitized = sanitized.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
  
  // Remove javascript: protocol
  sanitized = sanitized.replace(/javascript\s*:/gi, '');
  
  // Remove event handlers
  sanitized = sanitized.replace(/on\w+\s*=\s*["'][^"']*["']/gi, '');
  sanitized = sanitized.replace(/on\w+\s*=[^\s>]+/gi, '');
  
  // Remove potentially dangerous tags if not explicitly allowed
  const defaultDisallowedTags = ['script', 'iframe', 'object', 'embed', 'form', 'input', 'button'];
  const disallowedTags = options.allowedTags
    ? defaultDisallowedTags.filter((tag) => !options.allowedTags!.includes(tag))
    : defaultDisallowedTags;
  
  disallowedTags.forEach(tag => {
    const regex = new RegExp(`<${tag}[^>]*>|<\/${tag}>`, 'gi');
    sanitized = sanitized.replace(regex, '');
  });
  
  // Remove base64 data URIs (potential XSS vector)
  sanitized = sanitized.replace(/data\s*:[^,]*;base64/gi, '');
  
  // Apply length limit
  if (options.maxLength && sanitized.length > options.maxLength) {
    sanitized = sanitized.substring(0, options.maxLength);
  }
  
  return sanitized;
}

// ─── SQL Injection Prevention ─────────────────────────────────────────────────

/**
 * Detect potential SQL injection patterns in a string
 */
export function detectSQLInjection(input: string): boolean {
  if (typeof input !== 'string') return false;
  
  return SQL_INJECTION_PATTERNS.some(pattern => pattern.test(input));
}

/**
 * Escape special characters for safe SQL usage
 * Note: This is a fallback - always use parameterized queries with Prisma
 */
export function escapeSQLValue(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value !== 'string') return String(value);
  
  // Escape single quotes and backslashes
  return value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''")
    .replace(/"/g, '\\"')
    .replace(/;/g, '')
    .replace(/--/g, '');
}

// ─── HTML Sanitization ────────────────────────────────────────────────────────

/**
 * Strip all HTML tags from a string
 */
export function stripHtml(input: string): string {
  if (typeof input !== 'string') return String(input);
  return input.replace(/<[^>]*>/g, '');
}

/**
 * Sanitize HTML, optionally allowing specific tags
 */
export function sanitizeHtml(input: string, allowedTags: string[] = []): string {
  if (typeof input !== 'string') return String(input);
  
  let sanitized = input;
  
  if (allowedTags.length === 0) {
    // Strip all HTML
    return stripHtml(sanitized);
  }
  
  // Remove all tags except allowed ones
  const allTags = sanitized.match(/<\/?([a-z][a-z0-9]*)\b[^>]*>/gi) || [];
  allTags.forEach(tag => {
    const tagName = tag.match(/<\/?([a-z][a-z0-9]*)/i)?.[1]?.toLowerCase();
    if (tagName && !allowedTags.includes(tagName)) {
      sanitized = sanitized.replace(tag, '');
    }
  });
  
  return sanitized;
}

// ─── Input Validation Helpers ─────────────────────────────────────────────────

/**
 * Validate and sanitize a string input
 */
export function validateString(
  input: unknown,
  options: {
    minLength?: number;
    maxLength?: number;
    pattern?: RegExp;
    allowEmpty?: boolean;
    sanitizeXss?: boolean;
  } = {}
): ValidationResult<string> {
  const {
    minLength = 0,
    maxLength = 10000,
    pattern,
    allowEmpty = false,
    sanitizeXss = true,
  } = options;
  
  const errors: ValidationError[] = [];
  
  // Type check
  if (typeof input !== 'string') {
    return {
      success: false,
      errors: [{ field: 'input', message: 'Must be a string', code: 'INVALID_TYPE' }],
    };
  }
  
  let value = input;
  
  // Check empty
  if (!allowEmpty && value.trim().length === 0) {
    errors.push({ field: 'input', message: 'Cannot be empty', code: 'EMPTY_VALUE' });
  }
  
  // Length validation
  if (value.length < minLength) {
    errors.push({
      field: 'input',
      message: `Must be at least ${minLength} characters`,
      code: 'TOO_SHORT',
    });
  }
  
  if (value.length > maxLength) {
    errors.push({
      field: 'input',
      message: `Must be at most ${maxLength} characters`,
      code: 'TOO_LONG',
    });
  }
  
  // Pattern validation
  if (pattern && !pattern.test(value)) {
    errors.push({
      field: 'input',
      message: 'Does not match required pattern',
      code: 'INVALID_PATTERN',
    });
  }
  
  // XSS detection
  if (detectXSS(value)) {
    errors.push({
      field: 'input',
      message: 'Contains potentially dangerous content',
      code: 'XSS_DETECTED',
    });
  }
  
  // SQL injection detection
  if (detectSQLInjection(value)) {
    errors.push({
      field: 'input',
      message: 'Contains potentially dangerous SQL patterns',
      code: 'SQL_INJECTION_DETECTED',
    });
  }
  
  // Sanitize if requested
  if (sanitizeXss) {
    value = sanitizeXSS(value, { maxLength });
  }
  
  if (errors.length > 0) {
    return { success: false, errors };
  }
  
  return { success: true, data: value, sanitized: value };
}

/**
 * Validate an email address
 */
export function validateEmail(email: unknown): ValidationResult<string> {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return validateString(email, {
    maxLength: 255,
    pattern: emailRegex,
    allowEmpty: false,
  });
}

/**
 * Validate a phone number (Kenyan format)
 */
export function validatePhone(phone: unknown): ValidationResult<string> {
  // Kenyan phone formats: +254XXXXXXXXX, 07XXXXXXXX, 01XXXXXXXX
  const phoneRegex = /^(\+254|0)[71]\d{8}$/;
  return validateString(phone, {
    pattern: phoneRegex,
    allowEmpty: false,
  });
}

/**
 * Validate a UUID
 */
export function validateUUID(uuid: unknown): ValidationResult<string> {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  return validateString(uuid, {
    pattern: uuidRegex,
    allowEmpty: false,
  });
}

// ─── File Upload Validation ───────────────────────────────────────────────────

export interface FileValidationOptions {
  maxFileSize?: number; // in bytes
  allowedMimeTypes?: string[];
  allowedExtensions?: string[];
}

export interface ValidatedFile {
  name: string;
  size: number;
  type: string;
  sanitized: string;
}

/**
 * Validate file upload metadata
 */
export function validateFile(
  fileName: string,
  fileSize: number,
  mimeType: string,
  options: FileValidationOptions = {}
): ValidationResult<ValidatedFile> {
  const {
    maxFileSize = 10 * 1024 * 1024, // 10MB default
    allowedMimeTypes = [],
    allowedExtensions = [],
  } = options;
  
  const errors: ValidationError[] = [];
  
  // File size validation
  if (fileSize > maxFileSize) {
    errors.push({
      field: 'file',
      message: `File size exceeds maximum of ${maxFileSize} bytes`,
      code: 'FILE_TOO_LARGE',
    });
  }
  
  // MIME type validation
  if (allowedMimeTypes.length > 0 && !allowedMimeTypes.includes(mimeType)) {
    errors.push({
      field: 'file',
      message: `File type ${mimeType} is not allowed`,
      code: 'INVALID_FILE_TYPE',
    });
  }
  
  // Extension validation
  if (allowedExtensions.length > 0) {
    const extension = fileName.split('.').pop()?.toLowerCase();
    if (!extension || !allowedExtensions.includes(extension)) {
      errors.push({
        field: 'file',
        message: `File extension .${extension} is not allowed`,
        code: 'INVALID_EXTENSION',
      });
    }
  }
  
  // Sanitize filename
  const sanitized = fileName
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/_{2,}/g, '_')
    .substring(0, 255);
  
  if (errors.length > 0) {
    return { success: false, errors };
  }
  
  return {
    success: true,
    data: { name: sanitized, size: fileSize, type: mimeType, sanitized },
    sanitized: { name: sanitized, size: fileSize, type: mimeType, sanitized },
  };
}

// ─── Request Body Validation ──────────────────────────────────────────────────

/**
 * Recursively sanitize an object, removing sensitive fields and XSS content
 */
export function sanitizeObject<T extends Record<string, unknown>>(
  obj: T,
  options: {
    removeSensitive?: boolean;
    sanitizeStrings?: boolean;
    maxDepth?: number;
  } = {}
): T {
  const {
    removeSensitive = true,
    sanitizeStrings = true,
    maxDepth = 10,
  } = options;
  
  function sanitize(value: unknown, depth: number): unknown {
    if (depth > maxDepth) return '[MAX_DEPTH_EXCEEDED]';
    
    if (typeof value === 'string') {
      if (sanitizeStrings) {
        return sanitizeXSS(value);
      }
      return value;
    }
    
    if (Array.isArray(value)) {
      return value.map(item => sanitize(item, depth + 1));
    }
    
    if (value !== null && typeof value === 'object') {
      const result: Record<string, unknown> = {};
      for (const [key, val] of Object.entries(value as Record<string, unknown>)) {
        if (removeSensitive && SENSITIVE_FIELDS.includes(key.toLowerCase())) {
          result[key] = '[REDACTED]';
        } else {
          result[key] = sanitize(val, depth + 1);
        }
      }
      return result;
    }
    
    return value;
  }
  
  return sanitize(obj, 0) as T;
}

/**
 * Validate request body against a Zod schema with additional security checks
 */
export function validateRequestBody<T extends z.ZodType>(
  body: unknown,
  schema: T,
  options: {
    sanitize?: boolean;
    strict?: boolean;
  } = {}
): ValidationResult<z.infer<T>> {
  const { sanitize: shouldSanitize = true, strict: _strict = true } = options;
  
  const errors: ValidationError[] = [];
  
  // Check for XSS in string fields before validation
  if (typeof body === 'object' && body !== null) {
    const checkForXSS = (obj: unknown, path: string = ''): void => {
      if (typeof obj === 'string') {
        if (detectXSS(obj)) {
          errors.push({
            field: path || 'body',
            message: 'Contains potentially dangerous content',
            code: 'XSS_DETECTED',
          });
        }
      } else if (typeof obj === 'object' && obj !== null) {
        for (const [key, value] of Object.entries(obj)) {
          checkForXSS(value, path ? `${path}.${key}` : key);
        }
      }
    };
    checkForXSS(body);
  }
  
  // Sanitize if requested
  let processedBody = body;
  if (shouldSanitize && typeof body === 'object' && body !== null) {
    processedBody = sanitizeObject(body as Record<string, unknown>);
  }
  
  // Validate with Zod
  const result = schema.safeParse(processedBody);
  
  if (!result.success) {
     
    (result.error as any).issues.forEach((err: { path: PropertyKey[]; message: string; code: string }) => {
      errors.push({
        field: err.path.join('.'),
        message: err.message,
        code: err.code,
      });
    });
  }
  
  if (errors.length > 0) {
    return { success: false, errors };
  }
  
  return {
    success: true,
    data: result.data as z.infer<T>,
    sanitized: result.data as z.infer<T>,
  };
}

// ─── Zod Schema Helpers ───────────────────────────────────────────────────────

/**
 * Create a Zod string schema with built-in XSS sanitization
 */
export function xssSafeString(options?: {
  min?: number;
  max?: number;
  pattern?: RegExp;
   
}): any {
  return z.string()
    .min(options?.min ?? 0)
    .max(options?.max ?? 10000)
    .regex(options?.pattern ?? /.*/)
    .transform((val: string) => sanitizeXSS(val));
}

/**
 * Create a Zod schema for email validation
 */
export const emailSchema = z.string().email('Invalid email address').max(255);

/**
 * Create a Zod schema for UUID validation
 */
export const uuidSchema = z.string().uuid('Invalid UUID');

/**
 * Create a Zod schema for phone validation (Kenyan format)
 */
export const phoneSchema = z.string().regex(/^(\+254|0)[71]\d{8}$/, 'Invalid phone number');

// ─── Middleware Helper ────────────────────────────────────────────────────────

/**
 * Create a validation middleware for API routes
 */
export function createValidator<T extends z.ZodType>(schema: T) {
  return {
    validate: (body: unknown): ValidationResult<z.infer<T>> => {
      return validateRequestBody(body, schema);
    },
    
    validateOrThrow: (body: unknown): z.infer<T> => {
      const result = validateRequestBody(body, schema);
      if (!result.success) {
        const errorMessages = result.errors?.map(e => `${e.field}: ${e.message}`).join(', ') || 'Validation failed';
        throw new Error(errorMessages);
      }
      return result.data as z.infer<T>;
    },
  };
}

// ─── Export Default ───────────────────────────────────────────────────────────

export default {
  detectXSS,
  sanitizeXSS,
  detectSQLInjection,
  escapeSQLValue,
  stripHtml,
  sanitizeHtml,
  validateString,
  validateEmail,
  validatePhone,
  validateUUID,
  validateFile,
  sanitizeObject,
  validateRequestBody,
  xssSafeString,
  emailSchema,
  uuidSchema,
  phoneSchema,
  createValidator,
  SENSITIVE_FIELDS,
};

/**
 * Role-Based Access Control (RBAC) System for AfyaHero Health
 * 
 * Provides granular permission management:
 * - Define all roles and their permissions
