  return Promise.resolve(parseSignedSession(token));
}

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * Permission categories for different resource types
 */
export type PermissionCategory = 
  | 'patients'
  | 'appointments'
  | 'labs'
  | 'pharmacy'
  | 'billing'
  | 'reports'
  | 'users'
  | 'settings'
  | 'inventory'
  | 'beds'
  | 'queue'
  | 'handover'
  | 'teleconsult'
  | 'ai'
  | 'audit';

/**
 * Permission actions that can be performed on resources
 */
